// Culture card translations keyed by native language code, then card id
// Base data is in Spanish. This file provides overlays for other native languages.

type CardTr = { title: string; body: string; fact: string };

export const CULTURE_I18N: Record<string, Record<string, CardTr>> = {
  en: {
    'jp-c1': { title: 'The Art of おじぎ (Ojigi)', body: 'In Japan, bowing (おじぎ) is a fundamental form of communication. There are three types: eshaku (15°) for casual greetings, keirei (30°) for formal situations, and saikeirei (45°) for deep apologies or extreme gratitude.', fact: 'In the Tokyo subway, conductors bow to the empty train as a sign of respect.' },
    'jp-c2': { title: 'Sushi Etiquette', body: 'Eating sushi has rules: eat with hands or chopsticks (never a fork), dip the fish (not the rice) in soy sauce, and don\'t mix wasabi into the soy sauce. Ginger is eaten between pieces to cleanse the palate.', fact: 'Original sushi (narezushi) was fermented for months. Modern sushi (edomae) was invented in Tokyo as fast food.' },
    'jp-c3': { title: 'Shinto and Temples', body: 'Japan has two main religions that coexist: Shinto (神道) and Buddhism. Shinto shrines (jinja) have red torii gates, while Buddhist temples (otera) have incense burners. Most Japanese practice both.', fact: 'Japan has over 80,000 Shinto shrines—more than the number of convenience stores.' },
    'jp-c4': { title: 'Tatemae and Honne', body: 'Tatemae (建前) is the "public face" you show the world, while honne (本音) are your true feelings. In Japanese culture, maintaining group harmony (和 wa) is more important than direct individual expression.', fact: 'When a Japanese person says "ちょっと..." (chotto = a little), it generally means "no" indirectly.' },
    'jp-c5': { title: 'Hanami - Flower Viewing', body: 'Hanami (花見) is the tradition of gathering under cherry blossom trees (sakura) in spring. Families and friends picnic while enjoying the fleeting beauty of the flowers, a concept tied to mono no aware (物の哀れ).', fact: 'Cherry blossom season lasts only 1-2 weeks. Japan has an official "bloom forecast" every year.' },
    'fr-c1': { title: 'The Baguette: World Heritage', body: 'The baguette was declared UNESCO Intangible Heritage in 2022. A French person consumes on average half a baguette per day. By law, a "baguette de tradition" can only contain flour, water, yeast, and salt.', fact: 'Paris holds an annual best baguette competition. The winner supplies bread to the Élysée Palace for a year.' },
    'fr-c2': { title: 'La Bise - The French Greeting', body: 'La bise (cheek kiss) is the standard greeting among acquaintances in France. The number varies by region: 2 in Paris, 3 in Provence, 4 in some villages.', fact: 'During COVID, some French people invented the "elbow kiss" to maintain the tradition.' },
    'fr-c3': { title: 'The Country of 400 Cheeses', body: 'Charles de Gaulle said: "How can you govern a country that has 246 cheeses?" Today France has over 400 varieties. Each region has its specialty: Camembert (Normandy), Roquefort (Aveyron), Comté (Jura).', fact: 'France\'s oldest cheese, Roquefort, has its own natural cave for aging. Legend says it was discovered by accident.' },
    'fr-c4': { title: 'The Eiffel Tower - A Temporary "Mistake"', body: 'Built in 1889 for the World\'s Fair, the Eiffel Tower was meant to be demolished after 20 years. Many Parisians hated it, calling it a "metal skeleton." Today it\'s the most visited paid monument in the world.', fact: 'The Eiffel Tower grows about 15 cm in summer due to thermal expansion of the iron.' },
    'fr-c5': { title: 'French Cinema', body: 'France is the birthplace of cinema. The Lumière brothers held the first public screening in 1895 in Paris. The Nouvelle Vague revolutionized world cinema. Today, France protects its film industry with screen quotas.', fact: 'France has more cinemas per capita than any other country.' },
    'zh-c1': { title: 'Chinese New Year', body: 'The Spring Festival (春节) is China\'s most important celebration. It lasts 15 days and culminates with the Lantern Festival. Families gather for dinner, give red envelopes (红包) with money, and set off fireworks to scare away the monster Nian.', fact: 'During Chinese New Year, the largest annual human migration occurs: over 3 billion trips in 40 days.' },
    'zh-c2': { title: 'The Tea Ceremony', body: 'Tea (茶) is China\'s national drink with over 5,000 years of culture. There are six main types: green, white, yellow, oolong, black, and puerh. The tea ceremony (茶道) combines aesthetics, philosophy, and hospitality.', fact: 'In China, serving tea is a gesture of respect. Tapping the table with your fingers is how to say thanks without interrupting.' },
    'zh-c3': { title: 'Chinese Characters', body: 'Mandarin Chinese uses characters (汉字) with over 3,000 years of history. Two systems exist: simplified (mainland China) and traditional (Taiwan, Hong Kong). An educated adult knows about 6,000 characters.', fact: 'The most complex character has 64 strokes (𪚥). The Kangxi dictionary contains 47,035 characters.' },
    'zh-c4': { title: 'The Eight Cuisines of China', body: 'China has eight regional culinary traditions: Sichuan (spicy), Cantonese (dim sum), Shandong (seafood), Jiangsu (sweet), Zhejiang (fresh), Fujian (soups), Hunan (smoked), and Anhui (herbs).', fact: 'Dumplings (饺子) are eaten on New Year because their shape resembles ancient gold ingots, symbolizing prosperity.' },
    'zh-c5': { title: 'The Concept of 面子 (Miànzi)', body: 'Miànzi (面子) or "face" is fundamental in Chinese culture. Losing face means losing social respect. Giving someone face (给面子) means showing public respect. This concept influences business, family, and daily life.', fact: 'At a Chinese dinner, fighting to pay the bill (抢着买单) is a way of giving face and showing generosity.' },
    'de-c1': { title: 'Oktoberfest and Beer Culture', body: 'Germany has over 1,300 breweries and a purity law (Reinheitsgebot) from 1516 allowing only water, barley, and hops. Munich\'s Oktoberfest attracts over 6 million visitors annually.', fact: 'Oktoberfest actually starts in September. It was originally a celebration for Prince Ludwig I\'s wedding in 1810.' },
    'de-c2': { title: 'Christmas Markets (Weihnachtsmärkte)', body: 'German Christmas markets are world-famous. The oldest, in Dresden (Striezelmarkt), dates to 1434. They sell Glühwein, Lebkuchen, and handcrafted ornaments.', fact: 'The Christmas tree (Tannenbaum) is a German tradition that spread worldwide thanks to Prince Albert, Queen Victoria\'s husband.' },
    'de-c3': { title: 'The Autobahn and German Engineering', body: 'The Autobahn is famous for having no speed limit on many stretches. Germany is home to Mercedes-Benz, BMW, Porsche, Audi, and Volkswagen. Engineering is part of the national identity.', fact: 'Only 30% of the Autobahn has no speed limit. The recommended speed is 130 km/h but not mandatory.' },
    'de-c4': { title: 'The Land of Classical Music', body: 'Germany gave the world Bach, Beethoven, Brahms, Wagner, and Händel. The Berlin Philharmonic is one of the best orchestras in the world.', fact: 'Beethoven composed his Ninth Symphony while completely deaf. The "Ode to Joy" is the EU anthem.' },
    'de-c5': { title: 'Punctuality and Recycling', body: 'Germans highly value punctuality (Pünktlichkeit). Being 5 minutes late is rude. They\'re world leaders in recycling with the Pfand system and strict waste separation.', fact: 'Germany recycles 67% of its waste, the highest rate in the world.' },
    'it-c1': { title: 'Pasta: Over 300 Shapes', body: 'Italy has over 300 types of pasta, each designed for a specific sauce. Spaghetti goes with light sauces, rigatoni with thick sauces, tortellini in broth. Always cooked "al dente."', fact: 'Italians consume 23 kg of pasta per person per year. Putting ketchup on pasta is considered almost a crime.' },
    'it-c2': { title: 'Espresso Culture', body: 'Coffee in Italy is a social ritual. Espresso is drunk standing at the bar. Cappuccino is only in the morning. Ordering a "latte" gets you a glass of milk.', fact: 'Italy has over 200,000 coffee bars. Espresso prices at the counter are government-regulated in many cities.' },
    'it-c3': { title: 'Commedia dell\'Arte', body: 'Born in Italy in the 16th century, it\'s the basis of modern theater. Characters like Arlecchino, Pulcinella, and Colombina were archetypes with masks.', fact: 'Pulcinella is the ancestor of English Punch and French Polichinelle. Venice Carnival keeps the mask tradition alive.' },
    'it-c4': { title: 'Italian Gestures', body: 'Italy is famous for gestural communication with over 250 recognized gestures. The "pinched hand" gesture means "what do you want?"', fact: 'In 2020, the pinched hand gesture became an official emoji (🤌). Italians celebrated it as international cultural recognition.' },
    'it-c5': { title: 'Calcio and Sports Passion', body: 'Football (calcio) is more than a sport in Italy. Every city has its team. Italy has won 4 World Cups. Sunday football is sacred.', fact: 'Florence\'s "calcio storico" is a 16th-century sport combining football, rugby, and wrestling, played in Renaissance costumes.' },
    'pt-c1': { title: 'Saudade and Fado', body: 'Saudade is a Portuguese word with no exact translation: a mix of nostalgia, melancholy, and longing. Fado expresses saudade and is UNESCO Heritage since 2011.', fact: 'Amália Rodrigues was so important that Portugal declared three days of national mourning when she passed in 1999.' },
    'pt-c2': { title: 'Brazilian Football: Jogo Bonito', body: 'Brazil has won 5 World Cups, more than any other country. "Jogo bonito" prioritizes creativity and joy. Pelé, Garrincha, Ronaldo, and Neymar are icons.', fact: 'The Maracanã once held 200,000 spectators in 1950. Many Brazilian children learn football before reading.' },
    'pt-c3': { title: 'Rio Carnival', body: 'Rio Carnival is the world\'s largest popular festival with over 2 million people daily. Samba schools compete all year for their Sambadrome parades.', fact: 'Each samba school spends $2-5 million on their parade. Preparation begins right after the previous carnival.' },
    'pt-c4': { title: 'Pastéis de Nata', body: 'Pastéis de nata are Portugal\'s most emblematic sweet, created by Jerónimos monks in the 18th century. The recipe remains a guarded secret.', fact: 'Pastéis de Belém sells over 20,000 pastries per day. Only three people know the complete original recipe.' },
    'pt-c5': { title: 'Portuguese Discoveries', body: 'In the 15th-16th centuries, Portugal was the first global maritime power. Vasco da Gama reached India, Cabral discovered Brazil, Magellan began the first circumnavigation.', fact: 'Portugal has the world\'s oldest functioning bookshop: Livraria Bertrand, open since 1732 in Lisbon.' },
    'ko-c1': { title: 'K-Pop and Hallyu', body: 'The "Korean Wave" (한류) has turned South Korea into a cultural superpower. K-Pop generates billions. K-Dramas are watched in 190+ countries.', fact: 'BTS generated approximately $5 billion annually for the South Korean economy.' },
    'ko-c2': { title: 'Kimchi: Soul of the Korean Table', body: 'Kimchi is fermented vegetables with chili, garlic, and ginger. Every family has their own recipe. Mass preparation (김장) is UNESCO Heritage.', fact: 'South Korea has over 200 varieties of kimchi. Koreans consume 18 kg per person per year.' },
    'ko-c3': { title: 'Hangul: The Scientific Alphabet', body: 'King Sejong created hangul (한글) in 1443 so common people could read. It\'s one of the most scientific writing systems with 14 consonants and 10 vowels.', fact: 'Hangul can be taught in a few hours. Hangul Day (한글날) is celebrated October 9 as a national holiday.' },
    'ko-c4': { title: 'Jjimjilbang: Public Bath Culture', body: 'Jjimjilbang (찜질방) are 24/7 Korean public saunas. Social spaces for relaxing, sleeping, eating. They include hot, cold, salt, and jade rooms.', fact: 'Many Koreans spend the night at a jjimjilbang when they miss the last train. Only $8-12 for the whole night.' },
    'ko-c5': { title: 'Korean Education Fever', body: 'South Korea has one of the most intense educational cultures. The Suneung (수능) exam determines university futures. Planes stop flying during listening sections.', fact: 'On Suneung day, police escort late students, stock exchanges open late, and the nation falls silent during listening tests.' },
    'ru-c1': { title: 'The Matryoshka', body: 'Russian nesting dolls (матрёшка) are Russia\'s most recognizable symbol. They represent motherhood and fertility. The first was created in 1890, inspired by Japanese dolls.', fact: 'The largest matryoshka has 51 pieces and measures 1 meter tall, made in Semyonov.' },
    'ru-c2': { title: 'The Samovar and Tea Culture', body: 'The samovar heats water for tea. Russian tea time includes varenye (homemade jam), cookies, and long conversation. Tea is served concentrated and diluted to taste.', fact: 'Russians drink 1.3 kg of tea per person per year. Tradition: put sugar between teeth and sip tea through it.' },
    'ru-c3': { title: 'The Russian Soul and Literature', body: 'The "Russian soul" (русская душа) describes the emotional depth of Russian culture, reflected in Dostoevsky, Tolstoy, Chekhov, and Pushkin.', fact: 'Tolstoy wrote "War and Peace" with 580+ characters. His wife hand-copied the manuscript 7 times.' },
    'ru-c4': { title: 'The Russian Winter', body: 'Winter defines Russian culture. Temperatures can reach -50°C in Siberia. Russians celebrate Maslenitsa (Масленица) to bid winter farewell with blinis and bonfires.', fact: 'In Oymyakon, the coldest inhabited place, temperatures reach -71.2°C. Children go to school down to -52°C.' },
    'ru-c5': { title: 'The Soviet Space Age', body: 'Russia (as USSR) pioneered space: first satellite (Sputnik), first human in space (Gagarin), first spacewalk (Leonov).', fact: 'Gagarin said "Поехали!" (Let\'s go!) at launch. Every cosmonaut repeats it as tradition.' },
    'ar-c1': { title: 'Arabic Coffee and Hospitality', body: 'Arabic coffee (قهوة عربية) is a symbol of hospitality. Served in small handleless cups, flavored with cardamom, always offered to guests first.', fact: 'To decline more coffee, shake your cup side to side. If still, they\'ll pour more.' },
    'ar-c2': { title: 'Arabic Calligraphy as Art', body: 'Arabic calligraphy is the highest form of visual art in the Islamic world. Styles include Naskh, Thuluth, and Diwani.', fact: 'Arabic calligraphy became UNESCO Heritage in 2021. Some calligraphers use a single horse hair as a brush.' },
    'ar-c3': { title: 'Ramadan: The Holy Month', body: 'Ramadan is the ninth month of the Islamic calendar. Muslims fast from dawn to sunset, sharing Iftar in community.', fact: 'During Ramadan, date consumption increases 300%. Breaking fast with dates is a tradition from Prophet Muhammad.' },
    'ar-c4': { title: 'The Bedouins and the Desert', body: 'Bedouins (بدو) are nomadic desert peoples. Their honor code includes absolute hospitality: any traveler must be fed and protected for three days.', fact: 'Bedouins navigate the desert using stars with GPS-like precision.' },
    'ar-c5': { title: 'Arabic Music and the Oud', body: 'The oud (عود) is the oldest Middle Eastern string instrument, ancestor of the European lute. Arabic music uses the maqam system with microtonal scales.', fact: 'Um Kulthum\'s concerts could last 6 hours. A single song could extend for 2 hours of improvisation.' },
    'hi-c1': { title: 'Diwali: Festival of Lights', body: 'Diwali (दिवाली) celebrates the triumph of light over darkness. Families light diyas, make rangoli, exchange sweets, and set off fireworks.', fact: 'Diwali lasts 5 days. Satellites can photograph India glowing brighter from space during the festival.' },
    'hi-c2': { title: 'India\'s Culinary Diversity', body: 'India has 29 states with unique cuisines. The north prefers bread with curry, the south uses rice with sambar and dosa. Spices are the soul of everything.', fact: 'India produces 70% of world spices. Chai is consumed at 1 billion cups per day.' },
    'hi-c3': { title: 'The Sacred Cow', body: 'The cow is sacred in Hinduism. Beef isn\'t consumed in much of India. Cows walk freely through streets and have right of way.', fact: 'India has 300+ million cows. Some states have government-funded "cow hospitals" (gaushalas).' },
    'hi-c4': { title: 'Holi: Festival of Colors', body: 'Holi (होली) celebrates spring and the triumph of good. People throw colored powders (gulal) and colored water. Social differences are temporarily erased.', fact: 'Holi powder was originally made from medicinal flowers like neem and turmeric.' },
    'hi-c5': { title: 'Bollywood: The Dream Factory', body: 'Bollywood produces 1,500+ films per year, more than Hollywood. Films include songs, dances, and romance. Cinema is India\'s most popular entertainment.', fact: 'India sells 3 billion movie tickets per year, 4x more than the US.' },
    'tr-c1': { title: 'Turkish Coffee: World Heritage', body: 'Turkish coffee (Türk kahvesi) is UNESCO Heritage since 2013. Prepared in a cezve with finely ground coffee. Fortune-telling from the grounds is popular.', fact: 'Turkish proverb: "A cup of coffee creates a 40-year friendship." Brides put salt in the groom\'s coffee to test patience.' },
    'tr-c2': { title: 'The Turkish Hamam', body: 'The hamam combines hygiene and socializing. Ritual includes steam, exfoliation with a kese glove, and foam massage.', fact: 'Çemberlitaş Hamamı was designed by architect Sinan in 1584 and still operates at 440 years old.' },
    'tr-c3': { title: 'Cappadocia Hot Air Balloons', body: 'Cappadocia is famous for balloon flights over "fairy chimney" rock formations created by ancient volcanic eruptions.', fact: 'Each morning, up to 150 balloons launch simultaneously over Cappadocia.' },
    'tr-c4': { title: 'Nazar Boncuğu (Evil Eye)', body: 'The nazar boncuğu (blue eye) protects against the "evil eye." Found everywhere in Turkey. Blue is believed to absorb negative energy.', fact: 'Turkey produces 3+ million evil eye amulets per year, mostly handcrafted in Nazarköy ("evil eye village").' },
    'tr-c5': { title: 'Turkish Cuisine: Bridge Between Worlds', body: 'Turkish cuisine is one of three great culinary traditions (with French and Chinese). Turkish breakfast (kahvaltı) is a feast. Kebab has 40+ regional varieties.', fact: '"Kahvaltı" literally means "before coffee." Turkish baklava can have 40 layers of filo dough.' },
    'en-c1': { title: 'British Afternoon Tea', body: 'Afternoon tea was invented in 1840 by the Duchess of Bedford. It includes cucumber sandwiches, scones with cream, and pastries. The milk-pouring order is a national debate.', fact: 'The British drink 165 million cups of tea per day.' },
    'en-c2': { title: 'Anglo-Saxon Sports', body: 'England invented football, cricket, rugby, and tennis. The US created baseball, basketball, and American football. Sport is fundamental to the cultural identity.', fact: 'Football rules were written in a London pub in 1863. The Super Bowl draws 115 million viewers.' },
    'en-c3': { title: 'Shakespeare and Theater', body: 'Shakespeare wrote 37 plays and coined 1,700+ words still used today: "lonely," "generous," "eyeball," "bedroom."', fact: 'Nobody knows exactly what Shakespeare looked like. The famous portraits were painted after his death.' },
    'en-c4': { title: 'Fast Food and American Culture', body: 'The US popularized fast food with McDonald\'s (1955). Thanksgiving centers on turkey. American diversity created fusions like Tex-Mex.', fact: 'Americans consume 50 billion hamburgers per year—enough to circle Earth 32 times.' },
    'en-c5': { title: 'The American Dream', body: 'The belief that anyone can achieve success through hard work, regardless of origin. Present in literature, film, and music.', fact: 'The Statue of Liberty was a gift from France in 1886. Its 7 crown points represent 7 continents and 7 seas.' },
    'es-c1': { title: 'Flamenco: Passion and Duende', body: 'Flamenco combines cante, toque, and baile. "Duende" transforms performance into something transcendental. UNESCO Heritage since 2010.', fact: 'Flamenco footwork reaches 12 strikes per second. Pros wear through 3 pairs of shoes monthly.' },
    'es-c2': { title: 'Fiestas and Traditions', body: 'Spain has 25,000+ popular festivals per year. San Fermín, Las Fallas, La Tomatina, and Semana Santa are the best known.', fact: 'La Tomatina uses 150,000+ tomatoes in one hour.' },
    'es-c3': { title: 'Tapas: Social Eating', body: 'Tapas are small plates shared while drinking. Originally bread slices placed over glasses. Each region has specialties.', fact: 'In Granada and Salamanca, tapas are still free with drinks. Spain has more bars per capita than any EU country.' },
    'es-c4': { title: 'The Spanish Siesta', body: 'The siesta is a centuries-old Mediterranean tradition. Shops traditionally closed 2-5 PM. Disappearing in cities but alive in rural areas.', fact: 'Only 18% of Spaniards nap regularly. Spain has a national siesta championship.' },
    'es-c5': { title: 'Spanish Around the World', body: 'Spanish is the native language of 500 million people in 21 countries. Second most spoken native language after Mandarin.', fact: 'The US has more Spanish speakers than Spain. By 2060, the US may be the top Spanish-speaking country.' },
    'vi-c1': { title: 'Phở: The Soul of Vietnam', body: 'Phở is a rice noodle soup with aromatic bone broth and herbs. Eaten anytime, especially breakfast. Hanoi and Saigon styles differ.', fact: 'Vietnam consumes 2 million bowls of phở daily. The world record bowl weighed 1,300 kg.' },
    'vi-c2': { title: 'Motorbike Culture', body: 'Vietnam has 45+ million motorbikes for 100 million people. Used for everything: families, furniture, animals. Crossing the street is an art.', fact: 'Local rule in Hanoi: "walk slowly and confidently, the bikes will dodge you."' },
    'vi-c3': { title: 'Tết: Vietnamese New Year', body: 'Tết Nguyên Đán is Vietnam\'s most important holiday. Families clean, decorate with blossoms, and prepare bánh chưng (sticky rice cake).', fact: 'The first person to cross your threshold on Tết (xông đất) determines the year\'s luck.' },
    'vi-c4': { title: 'Terraced Rice Fields', body: 'Sapa and Mù Cang Chải\'s terraced rice fields are engineering masterpieces by Hmong and Dao peoples. Vietnam is the 3rd largest rice exporter.', fact: '"Have you eaten rice?" (Ăn cơm chưa?) is a daily greeting meaning "How are you?"' },
    'vi-c5': { title: 'The Nón Lá and Áo Dài', body: 'The nón lá (conical hat) and áo dài (long dress) are iconic Vietnamese symbols. The áo dài is worn at weddings and as school uniforms.', fact: 'The longest áo dài measured 638 meters, made by 20 seamstresses over 3 months.' },
    'th-c1': { title: 'The Wai: Thai Greeting', body: 'The wai (ไหว้) is pressing palms together and bowing. Higher hands = more respect. Younger people greet first.', fact: 'Thais wai to Buddha statues, spirits, and royal photos. 7-Eleven cashiers wai every customer.' },
    'th-c2': { title: 'The Monarchy and the King', body: 'The Thai monarchy is deeply respected. King Bhumibol reigned 70 years. Lèse-majesté is a serious crime. Yellow is the royal color.', fact: 'Thais stand for the royal anthem before every movie. Banknotes with the king are never stepped on.' },
    'th-c3': { title: 'Street Food Paradise', body: 'Thailand is a street food paradise. Bangkok is the world\'s best city for street food. Pad Thai, Som Tam, and Tom Yum cost under $2.', fact: 'Bangkok has 300,000+ street food stalls. Many Thais eat all three meals on the street.' },
    'th-c4': { title: 'The Elephant: National Symbol', body: 'The elephant is Thailand\'s national animal. White elephants are sacred and belong to the king. National Elephant Day is March 13.', fact: 'The expression "white elephant" comes from Thai kings gifting them to courtiers they wanted to ruin.' },
    'th-c5': { title: 'Theravada Buddhism', body: '95% of Thais are Theravada Buddhists. Men are expected to ordain as temporary monks at least once. Temples serve as community centers.', fact: 'Thailand has 40,000+ Buddhist temples. Every morning, monks walk barefoot collecting food alms.' },
    'nl-c1': { title: 'Tulips and Tulipmania', body: 'Tulips came from Turkey in the 16th century. In 1637, "Tulipmania" was the first speculative bubble: one bulb could cost as much as a house.', fact: 'Keukenhof plants 7 million bulbs yearly. A single field can have 3 million flowers.' },
    'nl-c2': { title: 'The Bicycle: Queen of Holland', body: 'Holland has more bikes than people: 23 million bikes for 17 million inhabitants. There are 35,000 km of bike paths.', fact: '800,000 bikes are stolen yearly. Amsterdam\'s canals yield about 15,000 bikes when dredged annually.' },
    'nl-c3': { title: 'Gouda, Edam, and Cheese', body: 'Holland produces 650+ million kg of cheese yearly. Traditional cheese markets in Gouda and Alkmaar have operated since the Middle Ages.', fact: '60% of Dutch cheese is exported. Dutch people eat 21 kg per person per year.' },
    'nl-c4': { title: 'The Fight Against Water', body: 'A third of Holland is below sea level. Polders and dikes are engineering feats. The Delta Works is one of the seven wonders of modern engineering.', fact: '"God created the world, but the Dutch created Holland." Without dikes, 65% would be flooded.' },
    'nl-c5': { title: 'Masters of Painting', body: 'Holland gave us Rembrandt, Vermeer, and Van Gogh. The Dutch Golden Age produced thousands of masterpieces.', fact: 'Van Gogh sold only one painting in his lifetime. "The Starry Night" was painted from a psychiatric hospital.' },
    'pl-c1': { title: 'Pierogi: Polish Dumplings', body: 'Pierogi are Poland\'s most iconic dish. Fillings include potatoes and cheese, meat, sauerkraut and mushrooms, or fruits.', fact: 'The largest pierogi weighed over 100 kg. Every Polish family guards their recipe as a secret.' },
    'pl-c2': { title: 'Christmas Eve (Wigilia)', body: 'Wigilia is Poland\'s most important celebration. An extra place is set for unexpected guests. Twelve meatless dishes are served.', fact: 'Straw is placed under the tablecloth to recall Jesus\' manger. Some families put coins under plates for prosperity.' },
    'pl-c3': { title: 'Chopin: The Soul of Poland', body: 'Chopin\'s piano music is among the most beautiful ever written. The Chopin Competition in Warsaw, held every 5 years, is the most prestigious piano competition.', fact: 'After death, Chopin\'s heart was smuggled to Warsaw in a cognac jar. It rests in the Holy Cross Church.' },
    'pl-c4': { title: 'Solidarity and Resilience', body: 'Poland has been invaded repeatedly but maintained its identity. Solidarity (Solidarność), led by Wałęsa, was the first independent Soviet bloc labor union.', fact: 'Poland disappeared from the map for 123 years (1795-1918) but kept its language alive through underground schools.' },
    'pl-c5': { title: 'The Polish Language', body: 'Polish is one of Europe\'s hardest languages with 7 cases, complex conjugations, and sounds like "szcz." Poles are proud of their linguistic heritage.', fact: 'The longest common Polish word is "najnieodpowiedzialniejszego" (32 letters). Poland has 5 Nobel laureates in Literature.' },
  },

  fr: {
    'jp-c1': { title: 'L\'art de l\'おじぎ (Ojigi)', body: 'Au Japon, la révérence (おじぎ) est une forme fondamentale de communication. Il existe trois types : eshaku (15°) pour les salutations décontractées, keirei (30°) pour les situations formelles, et saikeirei (45°) pour les excuses profondes.', fact: 'Dans le métro de Tokyo, les conducteurs s\'inclinent devant le train vide par respect.' },
    'jp-c2': { title: 'L\'étiquette du sushi', body: 'Manger des sushis a ses règles : on mange avec les mains ou les baguettes (jamais de fourchette), on trempe le poisson (pas le riz) dans la sauce soja, et on ne mélange pas le wasabi à la sauce.', fact: 'Le sushi original (narezushi) était fermenté pendant des mois. Le sushi moderne (edomae) a été inventé à Tokyo comme fast-food.' },
    'jp-c3': { title: 'Shintoïsme et temples', body: 'Le Japon a deux religions principales qui coexistent : le shintoïsme (神道) et le bouddhisme. Les sanctuaires shinto ont des torii rouges, tandis que les temples bouddhistes ont des brûleurs d\'encens.', fact: 'Le Japon compte plus de 80 000 sanctuaires shinto — plus que le nombre de konbini.' },
    'jp-c4': { title: 'Tatemae et Honne', body: 'Tatemae (建前) est le « visage public », tandis que honne (本音) représente les vrais sentiments. Maintenir l\'harmonie du groupe (和 wa) est plus important que l\'expression directe.', fact: 'Quand un Japonais dit « ちょっと... » (chotto), cela signifie généralement « non » de manière indirecte.' },
    'jp-c5': { title: 'Hanami - Contemplation des fleurs', body: 'Le hanami (花見) est la tradition de se réunir sous les cerisiers en fleur au printemps. Un concept lié au mono no aware (物の哀れ), la beauté éphémère.', fact: 'La saison des sakura ne dure que 1-2 semaines. Le Japon a un « bulletin de floraison » officiel chaque année.' },
    'fr-c1': { title: 'La baguette : patrimoine mondial', body: 'La baguette a été inscrite au Patrimoine immatériel de l\'UNESCO en 2022. Un Français consomme en moyenne une demi-baguette par jour. Par loi, une « baguette de tradition » ne peut contenir que farine, eau, levure et sel.', fact: 'Paris organise un concours annuel de la meilleure baguette. Le gagnant fournit le pain à l\'Élysée pendant un an.' },
    'fr-c2': { title: 'La bise - Le salut français', body: 'La bise est le salut standard entre connaissances. Le nombre varie selon la région : 2 à Paris, 3 en Provence, 4 dans certains villages.', fact: 'Pendant le COVID, certains Français ont inventé la « bise du coude » pour maintenir la tradition.' },
    'fr-c3': { title: 'Le pays aux 400 fromages', body: 'De Gaulle disait : « Comment gouverner un pays qui a 246 fromages ? » Aujourd\'hui, la France en compte plus de 400. Chaque région a sa spécialité.', fact: 'Le Roquefort, le plus ancien fromage français, mûrit dans sa propre grotte naturelle.' },
    'fr-c4': { title: 'La Tour Eiffel - Une « erreur » temporaire', body: 'Construite en 1889 pour l\'Exposition universelle, elle devait être démolie après 20 ans. Beaucoup de Parisiens la détestaient. Aujourd\'hui, c\'est le monument payant le plus visité au monde.', fact: 'La Tour Eiffel grandit d\'environ 15 cm en été à cause de la dilatation thermique du fer.' },
    'fr-c5': { title: 'Le cinéma français', body: 'La France est le berceau du cinéma. Les frères Lumière ont réalisé la première projection publique en 1895 à Paris. La Nouvelle Vague a révolutionné le cinéma mondial.', fact: 'La France a plus de cinémas par habitant que tout autre pays.' },
    'zh-c1': { title: 'Le Nouvel An chinois', body: 'La Fête du Printemps (春节) est la célébration la plus importante de Chine. Elle dure 15 jours. Les familles donnent des enveloppes rouges (红包) avec de l\'argent.', fact: 'Pendant le Nouvel An chinois, plus de 3 milliards de voyages sont effectués en 40 jours.' },
    'zh-c2': { title: 'La cérémonie du thé', body: 'Le thé (茶) est la boisson nationale de la Chine avec plus de 5 000 ans de culture. Six types principaux existent. La cérémonie du thé (茶道) combine esthétique et philosophie.', fact: 'En Chine, servir du thé est un geste de respect. Tapoter la table avec les doigts dit merci sans interrompre.' },
    'zh-c3': { title: 'Les caractères chinois', body: 'Le mandarin utilise des caractères (汉字) vieux de plus de 3 000 ans. Deux systèmes : simplifié (Chine continentale) et traditionnel (Taïwan, Hong Kong).', fact: 'Le caractère le plus complexe a 64 traits. Le dictionnaire Kangxi contient 47 035 caractères.' },
    'zh-c4': { title: 'Les huit cuisines de Chine', body: 'La Chine a huit traditions culinaires régionales : Sichuan (épicée), Cantonaise (dim sum), Shandong (fruits de mer), etc.', fact: 'Les raviolis (饺子) sont mangés au Nouvel An car leur forme rappelle les lingots d\'or anciens.' },
    'zh-c5': { title: 'Le concept de 面子 (Miànzi)', body: 'Miànzi (面子) ou « face » est fondamental dans la culture chinoise. Perdre la face signifie perdre le respect social.', fact: 'Au dîner chinois, se battre pour payer l\'addition est un moyen de donner la face et montrer sa générosité.' },
    'de-c1': { title: 'L\'Oktoberfest et la culture brassicole', body: 'L\'Allemagne compte plus de 1 300 brasseries et une loi de pureté (Reinheitsgebot) de 1516. L\'Oktoberfest de Munich attire plus de 6 millions de visiteurs.', fact: 'L\'Oktoberfest commence en fait en septembre. C\'était à l\'origine une fête pour le mariage du prince Louis Ier.' },
    'de-c2': { title: 'Les marchés de Noël', body: 'Les marchés de Noël allemands sont mondialement célèbres. Le plus ancien, à Dresde (Striezelmarkt), date de 1434. On y vend Glühwein et Lebkuchen.', fact: 'Le sapin de Noël est une tradition allemande diffusée grâce au prince Albert, époux de la reine Victoria.' },
    'de-c3': { title: 'L\'Autobahn et l\'ingénierie allemande', body: 'L\'Autobahn est célèbre pour l\'absence de limite de vitesse sur de nombreux tronçons. L\'Allemagne est le berceau de Mercedes, BMW, Porsche, Audi et VW.', fact: 'Seuls 30 % de l\'Autobahn n\'ont pas de limite. La vitesse recommandée est de 130 km/h.' },
    'de-c4': { title: 'Le pays de la musique classique', body: 'L\'Allemagne a donné au monde Bach, Beethoven, Brahms, Wagner et Händel. Le Philharmonique de Berlin est parmi les meilleurs orchestres.', fact: 'Beethoven a composé sa Neuvième Symphonie étant complètement sourd. L\'« Hymne à la joie » est l\'hymne de l\'UE.' },
    'de-c5': { title: 'Ponctualité et recyclage', body: 'Les Allemands valorisent la ponctualité (Pünktlichkeit). 5 minutes de retard, c\'est impoli. Ils sont leaders du recyclage avec le système Pfand.', fact: 'L\'Allemagne recycle 67 % de ses déchets, le taux le plus élevé au monde.' },
    'it-c1': { title: 'Les pâtes : plus de 300 formes', body: 'L\'Italie a plus de 300 types de pâtes, chacun conçu pour une sauce spécifique. Toujours cuites « al dente ».', fact: 'Les Italiens consomment 23 kg de pâtes par personne et par an. Mettre du ketchup est presque un crime.' },
    'it-c2': { title: 'La culture de l\'espresso', body: 'Le café en Italie est un rituel social. L\'espresso se boit debout au comptoir. Le cappuccino uniquement le matin.', fact: 'L\'Italie a plus de 200 000 cafés. Le prix de l\'espresso au comptoir est réglementé dans beaucoup de villes.' },
    'it-c3': { title: 'La Commedia dell\'Arte', body: 'Née en Italie au XVIe siècle, c\'est la base du théâtre moderne. Arlequin, Polichinelle et Colombine étaient des archétypes masqués.', fact: 'Polichinelle est l\'ancêtre du Punch anglais et du Polichinelle français.' },
    'it-c4': { title: 'Les gestes italiens', body: 'L\'Italie est célèbre pour sa communication gestuelle avec plus de 250 gestes reconnus.', fact: 'En 2020, le geste de la main pincée est devenu un emoji officiel (🤌).' },
    'it-c5': { title: 'Le calcio et la passion sportive', body: 'Le football (calcio) est plus qu\'un sport en Italie. L\'Italie a remporté 4 Coupes du Monde.', fact: 'Le « calcio storico » de Florence est un sport du XVIe siècle mêlant football, rugby et lutte.' },
    'pt-c1': { title: 'Saudade et Fado', body: 'La saudade est un mot portugais intraduisible : un mélange de nostalgie et de mélancolie. Le Fado l\'exprime, patrimoine UNESCO depuis 2011.', fact: 'Amália Rodrigues fut si importante que le Portugal a décrété trois jours de deuil national à sa mort.' },
    'pt-c2': { title: 'Le football brésilien : Jogo Bonito', body: 'Le Brésil a gagné 5 Coupes du Monde. Le « jogo bonito » privilégie la créativité et la joie.', fact: 'Le Maracanã a accueilli 200 000 spectateurs en 1950.' },
    'pt-c3': { title: 'Le Carnaval de Rio', body: 'Le Carnaval de Rio est la plus grande fête populaire du monde avec plus de 2 millions de personnes par jour dans les rues.', fact: 'Chaque école de samba dépense 2 à 5 millions de dollars pour son défilé.' },
    'pt-c4': { title: 'Pastéis de Nata', body: 'Les pastéis de nata sont le dessert le plus emblématique du Portugal, créé par des moines au XVIIIe siècle.', fact: 'Pastéis de Belém vend plus de 20 000 pâtisseries par jour. Seules 3 personnes connaissent la recette originale.' },
    'pt-c5': { title: 'Les découvertes portugaises', body: 'Aux XVe-XVIe siècles, le Portugal fut la première puissance maritime mondiale. Vasco de Gama atteignit l\'Inde, Cabral découvrit le Brésil.', fact: 'Le Portugal abrite la plus ancienne librairie en activité : Livraria Bertrand, ouverte depuis 1732.' },
    'ko-c1': { title: 'K-Pop et Hallyu', body: 'La « vague coréenne » (한류) a fait de la Corée du Sud une superpuissance culturelle. Le K-Pop génère des milliards.', fact: 'BTS a généré environ 5 milliards de dollars par an pour l\'économie sud-coréenne.' },
    'ko-c2': { title: 'Kimchi : l\'âme de la table coréenne', body: 'Le kimchi est un légume fermenté avec du piment, de l\'ail et du gingembre. Chaque famille a sa propre recette.', fact: 'La Corée du Sud compte plus de 200 variétés de kimchi.' },
    'ko-c3': { title: 'Hangul : l\'alphabet scientifique', body: 'Le roi Sejong a créé le hangul (한글) en 1443 pour que le peuple puisse lire et écrire. 14 consonnes et 10 voyelles.', fact: 'Le hangul peut s\'apprendre en quelques heures. Le 9 octobre est la fête nationale du Hangul.' },
    'ko-c4': { title: 'Jjimjilbang : culture du bain public', body: 'Les jjimjilbang (찜질방) sont des saunas publics coréens ouverts 24h/24. Espaces sociaux pour se détendre et dormir.', fact: 'Beaucoup de Coréens passent la nuit au jjimjilbang quand ils ratent le dernier train. Seulement 8-12 dollars.' },
    'ko-c5': { title: 'La fièvre éducative coréenne', body: 'La Corée du Sud a l\'une des cultures éducatives les plus intenses. L\'examen Suneung (수능) détermine l\'avenir universitaire.', fact: 'Le jour du Suneung, la police escorte les retardataires, les bourses ouvrent tard et la nation se tait.' },
    'ru-c1': { title: 'La Matriochka', body: 'Les poupées russes (матрёшка) sont le symbole le plus reconnaissable de Russie. Chaque poupée en contient une plus petite.', fact: 'La plus grande matriochka a 51 pièces et mesure 1 mètre de haut.' },
    'ru-c2': { title: 'Le Samovar et la culture du thé', body: 'Le samovar chauffe l\'eau pour le thé. Le goûter russe comprend de la varenye (confiture maison), des biscuits et de longues conversations.', fact: 'Les Russes boivent 1,3 kg de thé par personne et par an.' },
    'ru-c3': { title: 'L\'âme russe et la littérature', body: 'L\'« âme russe » (русская душа) décrit la profondeur émotionnelle de la culture russe, reflétée par Dostoïevski, Tolstoï, Tchekhov et Pouchkine.', fact: 'Tolstoï a écrit « Guerre et Paix » avec plus de 580 personnages.' },
    'ru-c4': { title: 'L\'hiver russe', body: 'L\'hiver définit la culture russe. Les températures atteignent -50°C en Sibérie. Les Russes célèbrent la Maslenitsa avec des blinis.', fact: 'À Oïmiakon, les températures atteignent -71,2°C. Les enfants vont à l\'école jusqu\'à -52°C.' },
    'ru-c5': { title: 'L\'ère spatiale soviétique', body: 'La Russie (URSS) a été pionnière dans l\'espace : premier satellite (Spoutnik), premier humain (Gagarine), première sortie extravéhiculaire (Leonov).', fact: 'Gagarine a dit « Поехали ! » (Allons-y !) au décollage. Chaque cosmonaute le répète depuis.' },
    'ar-c1': { title: 'Le café arabe et l\'hospitalité', body: 'Le café arabe (قهوة عربية) est un symbole d\'hospitalité. Servi dans de petites tasses, parfumé au cardamome, offert à l\'invité en premier.', fact: 'Pour refuser un autre café, agitez votre tasse de côté. Sinon, on vous en servira encore.' },
    'ar-c2': { title: 'La calligraphie arabe', body: 'La calligraphie arabe est la forme d\'art visuel la plus élevée du monde islamique. Styles : Naskh, Thuluth et Diwani.', fact: 'La calligraphie arabe est patrimoine UNESCO depuis 2021.' },
    'ar-c3': { title: 'Ramadan : le mois sacré', body: 'Le Ramadan est le neuvième mois du calendrier islamique. Les musulmans jeûnent de l\'aube au coucher du soleil et partagent l\'Iftar.', fact: 'Pendant le Ramadan, la consommation de dattes augmente de 300 %.' },
    'ar-c4': { title: 'Les Bédouins et le désert', body: 'Les Bédouins (بدو) sont des peuples nomades du désert. Leur code d\'honneur inclut une hospitalité absolue envers tout voyageur.', fact: 'Les Bédouins s\'orientent dans le désert grâce aux étoiles avec une précision comparable au GPS.' },
    'ar-c5': { title: 'La musique arabe et le Oud', body: 'Le oud (عود) est le plus ancien instrument à cordes du Moyen-Orient, ancêtre du luth européen. La musique arabe utilise le système maqam.', fact: 'Les concerts d\'Oum Kalthoum pouvaient durer 6 heures.' },
    'hi-c1': { title: 'Diwali : la Fête des Lumières', body: 'Diwali (दिवाली) célèbre le triomphe de la lumière sur les ténèbres. Les familles allument des diyas, font des rangolis et tirent des feux d\'artifice.', fact: 'Diwali dure 5 jours. Les satellites photographient l\'Inde plus brillante depuis l\'espace.' },
    'hi-c2': { title: 'La diversité culinaire indienne', body: 'L\'Inde a 29 États, chacun avec sa cuisine unique. Le nord préfère le pain avec du curry, le sud le riz avec du sambar.', fact: 'L\'Inde produit 70 % des épices mondiales. Le chai se consomme à 1 milliard de tasses par jour.' },
    'hi-c3': { title: 'La vache sacrée', body: 'La vache est sacrée dans l\'hindouisme. On ne mange pas de bœuf dans une grande partie de l\'Inde. Les vaches circulent librement dans les rues.', fact: 'L\'Inde a plus de 300 millions de vaches. Certains États ont des « hôpitaux pour vaches » (gaushalas).' },
    'hi-c4': { title: 'Holi : la Fête des Couleurs', body: 'Holi (होली) célèbre le printemps. On se lance des poudres colorées (gulal). Les différences sociales s\'effacent temporairement.', fact: 'La poudre de Holi était à l\'origine faite de fleurs médicinales comme le neem et le curcuma.' },
    'hi-c5': { title: 'Bollywood : l\'usine à rêves', body: 'Bollywood produit plus de 1 500 films par an, plus qu\'Hollywood. Les films incluent chansons, danses et romance.', fact: 'L\'Inde vend 3 milliards de billets de cinéma par an, 4 fois plus que les États-Unis.' },
    'tr-c1': { title: 'Le café turc : patrimoine mondial', body: 'Le café turc (Türk kahvesi) est patrimoine UNESCO depuis 2013. Préparé dans un cezve avec du café finement moulu. Lire l\'avenir dans le marc est populaire.', fact: 'Proverbe turc : « Une tasse de café crée une amitié de 40 ans. »' },
    'tr-c2': { title: 'Le Hamam turc', body: 'Le hamam combine hygiène et socialisation. Le rituel comprend vapeur, gommage au kese et massage à la mousse.', fact: 'Le Çemberlitaş Hamamı, conçu par l\'architecte Sinan en 1584, fonctionne toujours.' },
    'tr-c3': { title: 'Les montgolfières de Cappadoce', body: 'La Cappadoce est célèbre pour ses vols en montgolfière au-dessus des « cheminées de fées ».', fact: 'Chaque matin, jusqu\'à 150 montgolfières décollent simultanément au-dessus de la Cappadoce.' },
    'tr-c4': { title: 'Nazar Boncuğu (Œil turc)', body: 'Le nazar boncuğu (œil bleu) protège contre le « mauvais œil ». On le trouve partout en Turquie.', fact: 'La Turquie produit plus de 3 millions d\'amulettes par an, surtout à Nazarköy (« village du mauvais œil »).' },
    'tr-c5': { title: 'La cuisine turque : pont entre les mondes', body: 'La cuisine turque est l\'une des trois grandes traditions culinaires. Le petit-déjeuner turc (kahvaltı) est un festin. Le kebab a 40+ variétés.', fact: '« Kahvaltı » signifie littéralement « avant le café ». Le baklava turc peut avoir 40 couches de pâte filo.' },
    'en-c1': { title: 'Le thé britannique', body: 'L\'afternoon tea a été inventé en 1840 par la duchesse de Bedford. Il comprend sandwichs au concombre, scones et pâtisseries.', fact: 'Les Britanniques boivent 165 millions de tasses de thé par jour.' },
    'en-c2': { title: 'Les sports anglo-saxons', body: 'L\'Angleterre a inventé le football, le cricket, le rugby et le tennis. Les USA ont créé le baseball et le basketball.', fact: 'Les règles du football ont été écrites dans un pub de Londres en 1863.' },
    'en-c3': { title: 'Shakespeare et le théâtre', body: 'Shakespeare a écrit 37 pièces et inventé plus de 1 700 mots encore utilisés : « lonely », « generous », « eyeball ».', fact: 'Personne ne sait à quoi ressemblait Shakespeare. Les portraits célèbres ont été peints après sa mort.' },
    'en-c4': { title: 'Le fast-food et la culture américaine', body: 'Les USA ont popularisé le fast-food avec McDonald\'s (1955). Thanksgiving est centré sur la dinde. La diversité a créé des fusions comme le Tex-Mex.', fact: 'Les Américains consomment 50 milliards de hamburgers par an.' },
    'en-c5': { title: 'Le rêve américain', body: 'La croyance que n\'importe qui peut réussir par le travail, quel que soit son origine. Présent dans la littérature, le cinéma et la musique.', fact: 'La Statue de la Liberté était un cadeau de la France en 1886. Ses 7 pointes représentent les 7 continents.' },
    'es-c1': { title: 'Le flamenco : passion et duende', body: 'Le flamenco combine cante, toque et baile. Le « duende » transforme la performance en quelque chose de transcendantal. Patrimoine UNESCO depuis 2010.', fact: 'Le zapateado flamenco peut atteindre 12 frappes par seconde.' },
    'es-c2': { title: 'Fêtes et traditions', body: 'L\'Espagne a plus de 25 000 fêtes populaires par an. San Fermín, Las Fallas, La Tomatina et la Semana Santa sont les plus connues.', fact: 'La Tomatina utilise plus de 150 000 tomates en une heure.' },
    'es-c3': { title: 'Les tapas : manger en société', body: 'Les tapas sont de petits plats partagés entre amis. À l\'origine, des tranches de pain posées sur le verre pour le couvrir.', fact: 'À Grenade et Salamanque, les tapas sont encore gratuites avec une boisson.' },
    'es-c4': { title: 'La sieste espagnole', body: 'La sieste est une tradition méditerranéenne adoptée en Espagne. Les magasins fermaient de 14h à 17h. Elle disparaît en ville mais persiste en zone rurale.', fact: 'Seuls 18 % des Espagnols font encore la sieste. L\'Espagne a un championnat national de sieste.' },
    'es-c5': { title: 'L\'espagnol dans le monde', body: 'L\'espagnol est la langue maternelle de 500 millions de personnes dans 21 pays. Deuxième langue maternelle après le mandarin.', fact: 'Les USA ont plus d\'hispanophones que l\'Espagne. En 2060, les USA pourraient être le premier pays hispanophone.' },
    'vi-c1': { title: 'Phở : l\'âme du Vietnam', body: 'Le phở est une soupe de nouilles de riz avec un bouillon aromatique. Mangé à tout moment, surtout au petit-déjeuner.', fact: 'Le Vietnam consomme 2 millions de bols de phở par jour.' },
    'vi-c2': { title: 'La culture de la moto', body: 'Le Vietnam a plus de 45 millions de motos pour 100 millions d\'habitants. La moto sert à tout transporter.', fact: 'Règle locale à Hanoï : « Marchez lentement et avec confiance, les motos vous esquiveront. »' },
    'vi-c3': { title: 'Tết : Nouvel An vietnamien', body: 'Tết Nguyên Đán est la fête la plus importante du Vietnam. Les familles nettoient la maison et préparent des bánh chưng.', fact: 'La première personne à franchir votre seuil au Tết (xông đất) détermine la chance de l\'année.' },
    'vi-c4': { title: 'Les rizières en terrasses', body: 'Les rizières en terrasses de Sapa sont des chefs-d\'œuvre d\'ingénierie agricole des ethnies Hmong et Dao.', fact: '« Avez-vous mangé du riz ? » (Ăn cơm chưa?) est un salut quotidien signifiant « Comment allez-vous ? »' },
    'vi-c5': { title: 'Le Nón Lá et l\'Áo Dài', body: 'Le nón lá (chapeau conique) et l\'áo dài (robe longue) sont des symboles iconiques du Vietnam.', fact: 'Le plus long áo dài mesurait 638 mètres, confectionné par 20 couturières en 3 mois.' },
    'th-c1': { title: 'Le Wai : salut thaïlandais', body: 'Le wai (ไหว้) consiste à joindre les paumes et incliner la tête. Plus les mains sont hautes, plus le respect est grand.', fact: 'Les Thaïlandais font le wai aux statues de Bouddha et aux photos royales.' },
    'th-c2': { title: 'La monarchie et le Roi', body: 'La monarchie thaïlandaise est profondément respectée. Le crime de lèse-majesté est sévèrement puni. Le jaune est la couleur royale.', fact: 'Les Thaïlandais se lèvent pour l\'hymne royal avant chaque film au cinéma.' },
    'th-c3': { title: 'Street food : la cuisine de rue', body: 'La Thaïlande est un paradis de la cuisine de rue. Bangkok est la meilleure ville au monde pour le street food.', fact: 'Bangkok compte plus de 300 000 stands de nourriture de rue.' },
    'th-c4': { title: 'L\'éléphant : symbole national', body: 'L\'éléphant est l\'animal national de la Thaïlande. Les éléphants blancs sont sacrés et appartiennent au roi.', fact: 'L\'expression « éléphant blanc » vient des rois thaïlandais qui les offraient à des courtisans qu\'ils voulaient ruiner.' },
    'th-c5': { title: 'Le bouddhisme Theravada', body: '95 % des Thaïlandais sont bouddhistes Theravada. Les hommes doivent être ordonnés moines temporaires au moins une fois.', fact: 'La Thaïlande compte plus de 40 000 temples bouddhistes.' },
    'nl-c1': { title: 'Les tulipes et la Tulipomanie', body: 'Les tulipes sont arrivées de Turquie au XVIe siècle. En 1637, la « Tulipomanie » fut la première bulle spéculative.', fact: 'Le parc Keukenhof plante 7 millions de bulbes chaque année.' },
    'nl-c2': { title: 'Le vélo : roi des Pays-Bas', body: 'Les Pays-Bas ont plus de vélos que d\'habitants : 23 millions de vélos pour 17 millions de personnes.', fact: '800 000 vélos sont volés par an. Les canaux d\'Amsterdam donnent 15 000 vélos quand ils sont dragués.' },
    'nl-c3': { title: 'Gouda, Edam et la tradition fromagère', body: 'Les Pays-Bas produisent plus de 650 millions de kg de fromage par an.', fact: '60 % du fromage néerlandais est exporté. Un Néerlandais mange 21 kg de fromage par an.' },
    'nl-c4': { title: 'La lutte contre l\'eau', body: 'Un tiers des Pays-Bas est sous le niveau de la mer. Les polders et les digues sont des prouesses d\'ingénierie.', fact: '« Dieu a créé le monde, mais les Néerlandais ont créé la Hollande. »' },
    'nl-c5': { title: 'Les maîtres de la peinture', body: 'La Hollande a donné Rembrandt, Vermeer et Van Gogh. Le Siècle d\'or a produit des milliers de chefs-d\'œuvre.', fact: 'Van Gogh n\'a vendu qu\'un tableau de son vivant. « La Nuit étoilée » a été peinte dans un hôpital psychiatrique.' },
    'pl-c1': { title: 'Pierogi : les raviolis polonais', body: 'Les pierogi sont le plat le plus emblématique de Pologne. Garnitures : pommes de terre et fromage, viande, choucroute et champignons.', fact: 'Le plus gros pierogi pesait plus de 100 kg. Chaque famille polonaise garde sa recette secrète.' },
    'pl-c2': { title: 'Le Réveillon (Wigilia)', body: 'La Wigilia est la célébration la plus importante de Pologne. Une place supplémentaire est mise pour les invités inattendus. 12 plats sans viande.', fact: 'De la paille est placée sous la nappe en souvenir de la crèche.' },
    'pl-c3': { title: 'Chopin : l\'âme de la Pologne', body: 'La musique pour piano de Chopin est parmi les plus belles jamais écrites. Le Concours Chopin de Varsovie est le plus prestigieux.', fact: 'Après sa mort, le cœur de Chopin a été transporté clandestinement à Varsovie dans un bocal de cognac.' },
    'pl-c4': { title: 'Solidarité et résilience', body: 'La Pologne a été envahie plusieurs fois mais a toujours gardé son identité. Solidarność a contribué à la fin de la Guerre froide.', fact: 'La Pologne a disparu de la carte pendant 123 ans (1795-1918) mais a gardé sa langue vivante.' },
    'pl-c5': { title: 'La langue polonaise', body: 'Le polonais est l\'une des langues les plus difficiles d\'Europe avec 7 cas grammaticaux et des sons comme « szcz ».', fact: 'Le mot polonais courant le plus long a 32 lettres. La Pologne a 5 prix Nobel de littérature.' },
  },

  pt: {
    'jp-c1': { title: 'A arte do おじぎ (Ojigi)', body: 'No Japão, a reverência (おじぎ) é uma forma fundamental de comunicação. Existem três tipos: eshaku (15°) para cumprimentos casuais, keirei (30°) para situações formais, e saikeirei (45°) para desculpas profundas.', fact: 'No metrô de Tóquio, os condutores fazem reverência ao trem vazio como sinal de respeito.' },
    'jp-c2': { title: 'A etiqueta do sushi', body: 'Comer sushi tem regras: come-se com as mãos ou pauzinhos (nunca garfo), molha-se o peixe (não o arroz) no molho de soja, e não se mistura wasabi no molho.', fact: 'O sushi original (narezushi) era fermentado por meses. O sushi moderno (edomae) foi inventado em Tóquio como fast food.' },
    'jp-c3': { title: 'Xintoísmo e templos', body: 'O Japão tem duas religiões que coexistem: o xintoísmo (神道) e o budismo. Os santuários xintoístas têm torii vermelhos, os templos budistas têm incensários.', fact: 'O Japão tem mais de 80.000 santuários xintoístas — mais que lojas de conveniência.' },
    'jp-c4': { title: 'Tatemae e Honne', body: 'Tatemae (建前) é a "face pública", honne (本音) são os sentimentos verdadeiros. Manter a harmonia do grupo (和 wa) é mais importante que a expressão direta.', fact: 'Quando um japonês diz "ちょっと..." (chotto), geralmente significa "não" indiretamente.' },
    'jp-c5': { title: 'Hanami - Contemplação das flores', body: 'Hanami (花見) é a tradição de reunir-se sob as cerejeiras na primavera. Ligado ao conceito de mono no aware (物の哀れ), a beleza efêmera.', fact: 'A temporada de sakura dura apenas 1-2 semanas. O Japão tem uma "previsão de floração" oficial.' },
    'fr-c1': { title: 'A baguete: patrimônio mundial', body: 'A baguete foi declarada Patrimônio Imaterial da UNESCO em 2022. Um francês consome em média meia baguete por dia.', fact: 'Paris tem um concurso anual da melhor baguete. O vencedor fornece pão ao Palácio do Eliseu por um ano.' },
    'fr-c2': { title: 'La bise - O cumprimento francês', body: 'La bise (beijo na bochecha) é o cumprimento padrão na França. O número varia por região: 2 em Paris, 3 na Provença, 4 em algumas vilas.', fact: 'Durante a COVID, alguns franceses inventaram o "beijo de cotovelo" para manter a tradição.' },
    'fr-c3': { title: 'O país dos 400 queijos', body: 'De Gaulle disse: "Como governar um país com 246 queijos?" Hoje a França tem mais de 400 variedades.', fact: 'O Roquefort, o queijo mais antigo da França, tem sua própria caverna natural para maturação.' },
    'fr-c4': { title: 'A Torre Eiffel - Um "erro" temporário', body: 'Construída em 1889, deveria ser demolida após 20 anos. Muitos parisienses a odiavam. Hoje é o monumento pago mais visitado do mundo.', fact: 'A Torre Eiffel cresce cerca de 15 cm no verão devido à expansão térmica do ferro.' },
    'fr-c5': { title: 'O cinema francês', body: 'A França é o berço do cinema. Os irmãos Lumière fizeram a primeira exibição pública em 1895 em Paris.', fact: 'A França tem mais cinemas per capita que qualquer outro país.' },
    'zh-c1': { title: 'Ano Novo Chinês', body: 'O Festival da Primavera (春节) é a celebração mais importante da China. Dura 15 dias. Famílias dão envelopes vermelhos (红包) com dinheiro.', fact: 'Durante o Ano Novo Chinês, mais de 3 bilhões de viagens são feitas em 40 dias.' },
    'zh-c2': { title: 'A cerimônia do chá', body: 'O chá (茶) é a bebida nacional da China com mais de 5.000 anos de cultura. A cerimônia do chá (茶道) combina estética e filosofia.', fact: 'Na China, servir chá é um gesto de respeito. Bater na mesa com os dedos agradece sem interromper.' },
    'zh-c3': { title: 'Os caracteres chineses', body: 'O mandarim usa caracteres (汉字) com mais de 3.000 anos. Dois sistemas: simplificado (China continental) e tradicional (Taiwan, Hong Kong).', fact: 'O caractere mais complexo tem 64 traços. O dicionário Kangxi contém 47.035 caracteres.' },
    'zh-c4': { title: 'As oito cozinhas da China', body: 'A China tem oito tradições culinárias regionais: Sichuan (picante), Cantonesa (dim sum), Shandong (frutos do mar), etc.', fact: 'Os dumplings (饺子) são comidos no Ano Novo porque lembram lingotes de ouro antigos.' },
    'zh-c5': { title: 'O conceito de 面子 (Miànzi)', body: 'Miànzi (面子) ou "face" é fundamental na cultura chinesa. Perder a face significa perder o respeito social.', fact: 'Num jantar chinês, brigar para pagar a conta é uma forma de dar face e mostrar generosidade.' },
    'de-c1': { title: 'Oktoberfest e cultura cervejeira', body: 'A Alemanha tem mais de 1.300 cervejarias e uma lei de pureza (Reinheitsgebot) de 1516. A Oktoberfest atrai mais de 6 milhões de visitantes.', fact: 'A Oktoberfest na verdade começa em setembro. Originalmente era uma festa de casamento do príncipe Luís I.' },
    'de-c2': { title: 'Mercados de Natal (Weihnachtsmärkte)', body: 'Os mercados de Natal alemães são famosos mundialmente. O mais antigo, em Dresden, data de 1434.', fact: 'A árvore de Natal é uma tradição alemã espalhada pelo mundo graças ao príncipe Alberto.' },
    'de-c3': { title: 'A Autobahn e a engenharia alemã', body: 'A Autobahn é famosa por não ter limite de velocidade em muitos trechos. Berço de Mercedes, BMW, Porsche, Audi e VW.', fact: 'Apenas 30% da Autobahn não tem limite. A velocidade recomendada é 130 km/h.' },
    'de-c4': { title: 'A terra da música clássica', body: 'A Alemanha deu ao mundo Bach, Beethoven, Brahms, Wagner e Händel.', fact: 'Beethoven compôs a Nona Sinfonia completamente surdo. A "Ode à Alegria" é o hino da UE.' },
    'de-c5': { title: 'Pontualidade e reciclagem', body: 'Os alemães valorizam muito a pontualidade. 5 minutos de atraso é falta de educação. Líderes em reciclagem com o sistema Pfand.', fact: 'A Alemanha recicla 67% dos seus resíduos, a taxa mais alta do mundo.' },
    'it-c1': { title: 'Massa: mais de 300 formatos', body: 'A Itália tem mais de 300 tipos de massa, cada um para um molho específico. Sempre cozida "al dente".', fact: 'Italianos consomem 23 kg de massa por pessoa/ano. Colocar ketchup na massa é quase um crime.' },
    'it-c2': { title: 'A cultura do espresso', body: 'O café na Itália é um ritual social. Espresso é tomado de pé no balcão. Cappuccino só de manhã.', fact: 'A Itália tem mais de 200.000 cafés. O preço do espresso no balcão é regulado pelo governo.' },
    'it-c3': { title: 'Commedia dell\'Arte', body: 'Nascida na Itália no séc. XVI, é a base do teatro moderno. Arlequim, Polichinelo e Colombina eram arquétipos com máscaras.', fact: 'Polichinelo é ancestral do Punch inglês. O Carnaval de Veneza mantém a tradição das máscaras.' },
    'it-c4': { title: 'Gestos italianos', body: 'A Itália é famosa pela comunicação gestual com mais de 250 gestos reconhecidos.', fact: 'Em 2020, o gesto da mão pinçada virou emoji oficial (🤌).' },
    'it-c5': { title: 'Calcio e paixão esportiva', body: 'O futebol (calcio) é mais que esporte na Itália. 4 Copas do Mundo conquistadas. O domingo de futebol é sagrado.', fact: 'O "calcio storico" de Florença é um esporte do séc. XVI que combina futebol, rugby e luta.' },
    'pt-c1': { title: 'Saudade e Fado', body: 'Saudade é uma palavra sem tradução exata: uma mistura de nostalgia e melancolia. O Fado expressa a saudade, patrimônio UNESCO desde 2011.', fact: 'Amália Rodrigues foi tão importante que Portugal decretou três dias de luto nacional quando faleceu.' },
    'pt-c2': { title: 'Futebol brasileiro: Jogo Bonito', body: 'O Brasil ganhou 5 Copas do Mundo. O "jogo bonito" prioriza criatividade e alegria. Pelé, Garrincha, Ronaldo e Neymar são ícones.', fact: 'O Maracanã chegou a ter 200.000 espectadores em 1950.' },
    'pt-c3': { title: 'Carnaval do Rio', body: 'O Carnaval do Rio é a maior festa popular do mundo, com mais de 2 milhões de pessoas nas ruas por dia.', fact: 'Cada escola de samba gasta 2 a 5 milhões de dólares no desfile.' },
    'pt-c4': { title: 'Pastéis de Nata', body: 'Os pastéis de nata são o doce mais emblemático de Portugal, criado por monges jerónimos no séc. XVIII.', fact: 'A Pastéis de Belém vende mais de 20.000 pastéis por dia. Só 3 pessoas conhecem a receita original.' },
    'pt-c5': { title: 'Os Descobrimentos Portugueses', body: 'Nos sécs. XV-XVI, Portugal foi a primeira potência marítima mundial. Vasco da Gama chegou à Índia, Cabral descobriu o Brasil.', fact: 'Portugal tem a livraria mais antiga do mundo em funcionamento: Livraria Bertrand, aberta desde 1732.' },
    'ko-c1': { title: 'K-Pop e Hallyu', body: 'A "Onda Coreana" (한류) transformou a Coreia do Sul em superpotência cultural. O K-Pop gera bilhões.', fact: 'BTS gerou cerca de 5 bilhões de dólares anuais para a economia sul-coreana.' },
    'ko-c2': { title: 'Kimchi: alma da mesa coreana', body: 'Kimchi é vegetal fermentado com pimenta, alho e gengibre. Cada família tem sua receita. O gimjang é patrimônio UNESCO.', fact: 'A Coreia do Sul tem mais de 200 variedades de kimchi.' },
    'ko-c3': { title: 'Hangul: o alfabeto científico', body: 'O rei Sejong criou o hangul (한글) em 1443 para que o povo pudesse ler e escrever. 14 consoantes e 10 vogais.', fact: 'O hangul pode ser aprendido em poucas horas. O Dia do Hangul é feriado nacional em 9 de outubro.' },
    'ko-c4': { title: 'Jjimjilbang: cultura do banho público', body: 'Os jjimjilbang (찜질방) são saunas públicas coreanas 24h. Espaços sociais para relaxar, dormir e comer.', fact: 'Muitos coreanos passam a noite no jjimjilbang quando perdem o último trem. Apenas $8-12.' },
    'ko-c5': { title: 'A febre educacional coreana', body: 'A Coreia do Sul tem uma das culturas educacionais mais intensas. O exame Suneung (수능) determina o futuro universitário.', fact: 'No dia do Suneung, a polícia escolta alunos atrasados e a nação silencia durante as provas de escuta.' },
    'ru-c1': { title: 'A Matrioshka', body: 'As bonecas russas (матрёшка) são o símbolo mais reconhecível da Rússia. Representam maternidade e fertilidade.', fact: 'A maior matrioshka tem 51 peças e mede 1 metro de altura.' },
    'ru-c2': { title: 'O Samovar e a cultura do chá', body: 'O samovar aquece água para o chá. A hora do chá russo inclui varenye (geleia caseira) e longas conversas.', fact: 'Os russos bebem 1,3 kg de chá por pessoa/ano.' },
    'ru-c3': { title: 'A alma russa e a literatura', body: 'A "alma russa" (русская душа) descreve a profundidade emocional da cultura russa, refletida em Dostoiévski, Tolstói e Tchekhov.', fact: 'Tolstói escreveu "Guerra e Paz" com mais de 580 personagens.' },
    'ru-c4': { title: 'O inverno russo', body: 'O inverno define a cultura russa. Temperaturas podem chegar a -50°C na Sibéria. Russos celebram a Maslenitsa com blinis.', fact: 'Em Oymyakon, as temperaturas chegam a -71,2°C. Crianças vão à escola até -52°C.' },
    'ru-c5': { title: 'A era espacial soviética', body: 'A Rússia (URSS) foi pioneira no espaço: primeiro satélite (Sputnik), primeiro humano (Gagarin), primeira caminhada espacial (Leonov).', fact: 'Gagarin disse "Поехали!" (Vamos!) na decolagem. Todo cosmonauta repete como tradição.' },
    'ar-c1': { title: 'Café árabe e hospitalidade', body: 'O café árabe (قهوة عربية) é símbolo de hospitalidade. Servido em xícaras pequenas sem alça, com cardamomo.', fact: 'Para recusar mais café, balance a xícara de lado a lado.' },
    'ar-c2': { title: 'Caligrafia árabe como arte', body: 'A caligrafia árabe é a forma mais elevada de arte visual no mundo islâmico.', fact: 'A caligrafia árabe é patrimônio UNESCO desde 2021.' },
    'ar-c3': { title: 'Ramadã: o mês sagrado', body: 'O Ramadã é o nono mês do calendário islâmico. Muçulmanos jejuam do amanhecer ao pôr do sol.', fact: 'Durante o Ramadã, o consumo de tâmaras aumenta 300%.' },
    'ar-c4': { title: 'Os beduínos e o deserto', body: 'Os beduínos (بدو) são povos nômades do deserto com tradições milenares de hospitalidade absoluta.', fact: 'Os beduínos se orientam pelas estrelas com precisão comparável ao GPS.' },
    'ar-c5': { title: 'Música árabe e o Oud', body: 'O oud (عود) é o instrumento de cordas mais antigo do Oriente Médio, ancestral do alaúde europeu.', fact: 'Os concertos de Um Kulthum podiam durar 6 horas.' },
    'hi-c1': { title: 'Diwali: Festival das Luzes', body: 'Diwali (दिवाली) celebra o triunfo da luz sobre as trevas. Famílias acendem diyas, fazem rangoli e soltam fogos.', fact: 'Diwali dura 5 dias. Satélites fotografam a Índia mais brilhante do espaço.' },
    'hi-c2': { title: 'Diversidade culinária da Índia', body: 'A Índia tem 29 estados com cozinhas únicas. O norte prefere pão com curry, o sul arroz com sambar.', fact: 'A Índia produz 70% das especiarias do mundo. O chai é consumido em 1 bilhão de xícaras/dia.' },
    'hi-c3': { title: 'A vaca sagrada', body: 'A vaca é sagrada no hinduísmo. Não se come carne bovina em grande parte da Índia. Vacas andam livremente.', fact: 'A Índia tem mais de 300 milhões de vacas. Alguns estados têm "hospitais para vacas".' },
    'hi-c4': { title: 'Holi: Festival das Cores', body: 'Holi (होली) celebra a primavera. Pessoas jogam pós coloridos (gulal). Diferenças sociais se apagam temporariamente.', fact: 'O pó de Holi era feito originalmente de flores medicinais como neem e cúrcuma.' },
    'hi-c5': { title: 'Bollywood: a fábrica de sonhos', body: 'Bollywood produz mais de 1.500 filmes por ano, mais que Hollywood. Cinema é o entretenimento mais popular da Índia.', fact: 'A Índia vende 3 bilhões de ingressos de cinema por ano, 4x mais que os EUA.' },
    'tr-c1': { title: 'Café turco: patrimônio mundial', body: 'O café turco (Türk kahvesi) é patrimônio UNESCO desde 2013. Preparado num cezve com café finamente moído.', fact: 'Provérbio turco: "Uma xícara de café cria uma amizade de 40 anos."' },
    'tr-c2': { title: 'O Hamam turco', body: 'O hamam combina higiene e socialização. O ritual inclui vapor, esfoliação com kese e massagem com espuma.', fact: 'O Çemberlitaş Hamamı foi projetado pelo arquiteto Sinan em 1584 e ainda funciona.' },
    'tr-c3': { title: 'Balões da Capadócia', body: 'A Capadócia é famosa por voos de balão sobre "chaminés de fadas" criadas por erupções vulcânicas.', fact: 'Cada manhã, até 150 balões decolam simultaneamente sobre a Capadócia.' },
    'tr-c4': { title: 'Nazar Boncuğu (Olho turco)', body: 'O nazar boncuğu (olho azul) protege contra o "mau-olhado". Encontrado por toda a Turquia.', fact: 'A Turquia produz mais de 3 milhões de amuletos por ano, principalmente em Nazarköy.' },
    'tr-c5': { title: 'Culinária turca: ponte entre mundos', body: 'A culinária turca é uma das três grandes tradições (com francesa e chinesa). O café da manhã turco (kahvaltı) é um banquete.', fact: '"Kahvaltı" significa literalmente "antes do café". O baklava turco pode ter 40 camadas de massa filo.' },
    'en-c1': { title: 'O chá da tarde britânico', body: 'O afternoon tea foi inventado em 1840 pela Duquesa de Bedford. Inclui sanduíches de pepino, scones e doces.', fact: 'Os britânicos bebem 165 milhões de xícaras de chá por dia.' },
    'en-c2': { title: 'Esportes anglo-saxões', body: 'A Inglaterra inventou o futebol, cricket, rugby e tênis. Os EUA criaram beisebol, basquete e futebol americano.', fact: 'As regras do futebol foram escritas num pub de Londres em 1863.' },
    'en-c3': { title: 'Shakespeare e o teatro', body: 'Shakespeare escreveu 37 peças e criou mais de 1.700 palavras ainda usadas hoje.', fact: 'Ninguém sabe exatamente como Shakespeare era. Os retratos famosos foram pintados após sua morte.' },
    'en-c4': { title: 'Fast food e cultura americana', body: 'Os EUA popularizaram o fast food com o McDonald\'s (1955). Thanksgiving é centrado no peru.', fact: 'Americanos consomem 50 bilhões de hambúrgueres por ano.' },
    'en-c5': { title: 'O sonho americano', body: 'A crença de que qualquer pessoa pode ter sucesso pelo trabalho duro, independente da origem.', fact: 'A Estátua da Liberdade foi um presente da França em 1886. Suas 7 pontas representam os 7 continentes.' },
    'es-c1': { title: 'Flamenco: paixão e duende', body: 'O flamenco combina cante, toque e baile. O "duende" transforma a performance em algo transcendental. Patrimônio UNESCO desde 2010.', fact: 'O sapateado flamenco pode atingir 12 batidas por segundo.' },
    'es-c2': { title: 'Festas e tradições', body: 'A Espanha tem mais de 25.000 festas populares por ano. San Fermín, Las Fallas, La Tomatina e Semana Santa são as mais conhecidas.', fact: 'La Tomatina usa mais de 150.000 tomates em uma hora.' },
    'es-c3': { title: 'Tapas: comer socializado', body: 'Tapas são pequenos pratos compartilhados entre amigos. Originalmente, fatias de pão colocadas sobre o copo.', fact: 'Em Granada e Salamanca, tapas ainda são grátis com bebida.' },
    'es-c4': { title: 'A siesta espanhola', body: 'A siesta é tradição mediterrânea adotada na Espanha. Lojas fechavam das 14h às 17h. Desaparecendo nas cidades.', fact: 'Apenas 18% dos espanhóis dormem siesta. A Espanha tem campeonato nacional de siesta.' },
    'es-c5': { title: 'O espanhol no mundo', body: 'O espanhol é língua nativa de 500 milhões em 21 países. Segunda língua materna mais falada após o mandarim.', fact: 'Os EUA têm mais falantes de espanhol que a Espanha.' },
    'vi-c1': { title: 'Phở: a alma do Vietnã', body: 'Phở é uma sopa de macarrão de arroz com caldo aromático. Consumido a qualquer hora, especialmente no café da manhã.', fact: 'O Vietnã consome 2 milhões de tigelas de phở por dia.' },
    'vi-c2': { title: 'Cultura da moto', body: 'O Vietnã tem mais de 45 milhões de motos para 100 milhões de habitantes. A moto serve para tudo.', fact: 'Regra local em Hanói: "Caminhe devagar e com confiança, as motos desviam de você."' },
    'vi-c3': { title: 'Tết: Ano Novo vietnamita', body: 'Tết Nguyên Đán é o feriado mais importante do Vietnã. Famílias limpam a casa e preparam bánh chưng.', fact: 'A primeira pessoa a cruzar sua porta no Tết (xông đất) determina a sorte do ano.' },
    'vi-c4': { title: 'Arrozais em terraço', body: 'Os arrozais em terraço de Sapa são obras-primas de engenharia agrícola das etnias Hmong e Dao.', fact: '"Você já comeu arroz?" (Ăn cơm chưa?) é um cumprimento diário que significa "Como vai?"' },
    'vi-c5': { title: 'O Nón Lá e o Áo Dài', body: 'O nón lá (chapéu cônico) e o áo dài (vestido longo) são símbolos icônicos do Vietnã.', fact: 'O maior áo dài do mundo tinha 638 metros, feito por 20 costureiras em 3 meses.' },
    'th-c1': { title: 'O Wai: cumprimento tailandês', body: 'O wai (ไหว้) é juntar as palmas e inclinar a cabeça. Quanto mais altas as mãos, mais respeito.', fact: 'Tailandeses fazem wai até para estátuas de Buda e fotos da família real.' },
    'th-c2': { title: 'A monarquia e o Rei', body: 'A monarquia tailandesa é profundamente respeitada. Crime de lesa-majestade é sério. Amarelo é a cor real.', fact: 'Tailandeses ficam de pé para o hino real antes de cada filme no cinema.' },
    'th-c3': { title: 'Street food: cozinha de rua', body: 'A Tailândia é um paraíso da comida de rua. Bangkok é a melhor cidade do mundo para street food.', fact: 'Bangkok tem mais de 300.000 barracas de comida de rua.' },
    'th-c4': { title: 'O elefante: símbolo nacional', body: 'O elefante é o animal nacional da Tailândia. Elefantes brancos são sagrados e pertencem ao rei.', fact: 'A expressão "elefante branco" vem dos reis tailandeses que os davam a cortesãos que queriam arruinar.' },
    'th-c5': { title: 'Budismo Theravada', body: '95% dos tailandeses são budistas Theravada. Homens devem ser monges temporários ao menos uma vez na vida.', fact: 'A Tailândia tem mais de 40.000 templos budistas.' },
    'nl-c1': { title: 'Tulipas e Tulipomania', body: 'As tulipas chegaram da Turquia no séc. XVI. Em 1637, a "Tulipomania" foi a primeira bolha especulativa da história.', fact: 'O parque Keukenhof planta 7 milhões de bulbos por ano.' },
    'nl-c2': { title: 'A bicicleta: rainha da Holanda', body: 'A Holanda tem mais bicicletas que habitantes: 23 milhões para 17 milhões de pessoas.', fact: '800.000 bicicletas são roubadas por ano. Os canais de Amsterdã rendem 15.000 bicicletas ao serem dragados.' },
    'nl-c3': { title: 'Gouda, Edam e tradição queijeira', body: 'A Holanda produz mais de 650 milhões de kg de queijo por ano.', fact: '60% do queijo holandês é exportado. Um holandês come 21 kg de queijo por ano.' },
    'nl-c4': { title: 'A luta contra a água', body: 'Um terço da Holanda está abaixo do nível do mar. Polders e diques são proezas de engenharia.', fact: '"Deus criou o mundo, mas os holandeses criaram a Holanda."' },
    'nl-c5': { title: 'Mestres da pintura', body: 'A Holanda deu ao mundo Rembrandt, Vermeer e Van Gogh.', fact: 'Van Gogh vendeu apenas um quadro em vida. "A Noite Estrelada" foi pintada num hospital psiquiátrico.' },
    'pl-c1': { title: 'Pierogi: os pastéis poloneses', body: 'Pierogi são o prato mais icônico da Polônia. Recheios: batata e queijo, carne, chucrute e cogumelos.', fact: 'O maior pierogi pesou mais de 100 kg. Cada família polonesa guarda sua receita.' },
    'pl-c2': { title: 'Véspera de Natal (Wigilia)', body: 'A Wigilia é a celebração mais importante da Polônia. Um lugar extra é posto para convidados inesperados. 12 pratos sem carne.', fact: 'Palha é colocada sob a toalha em memória do presépio.' },
    'pl-c3': { title: 'Chopin: a alma da Polônia', body: 'A música para piano de Chopin está entre as mais belas já escritas. O Concurso Chopin é o mais prestigioso do mundo.', fact: 'Após sua morte, o coração de Chopin foi levado clandestinamente a Varsóvia num frasco de conhaque.' },
    'pl-c4': { title: 'Solidariedade e resiliência', body: 'A Polônia foi invadida várias vezes mas manteve sua identidade. O Solidarność ajudou a acabar com a Guerra Fria.', fact: 'A Polônia desapareceu do mapa por 123 anos (1795-1918) mas manteve sua língua viva.' },
    'pl-c5': { title: 'A língua polonesa', body: 'O polonês é uma das línguas mais difíceis da Europa com 7 casos gramaticais e sons como "szcz".', fact: 'A palavra polonesa comum mais longa tem 32 letras. A Polônia tem 5 prêmios Nobel de Literatura.' },
  },

  de: {
    'jp-c1': { title: 'Die Kunst des おじぎ (Ojigi)', body: 'In Japan ist die Verbeugung (おじぎ) eine grundlegende Kommunikationsform. Es gibt drei Typen: Eshaku (15°), Keirei (30°) und Saikeirei (45°).', fact: 'In der Tokioter U-Bahn verbeugen sich die Zugführer vor dem leeren Zug als Zeichen des Respekts.' },
    'jp-c2': { title: 'Sushi-Etikette', body: 'Sushi essen hat Regeln: mit den Händen oder Stäbchen (nie Gabel), den Fisch (nicht den Reis) in Sojasauce tauchen, Wasabi nicht in die Sauce mischen.', fact: 'Ursprüngliches Sushi (Narezushi) wurde monatelang fermentiert. Modernes Sushi (Edomae) wurde als Fast Food erfunden.' },
    'jp-c3': { title: 'Shinto und Tempel', body: 'Japan hat zwei koexistierende Religionen: Shinto (神道) und Buddhismus. Shinto-Schreine haben rote Torii, buddhistische Tempel haben Räuchergefäße.', fact: 'Japan hat über 80.000 Shinto-Schreine — mehr als Convenience Stores.' },
    'jp-c4': { title: 'Tatemae und Honne', body: 'Tatemae (建前) ist das „öffentliche Gesicht", Honne (本音) die wahren Gefühle. Gruppenharmonie (和 wa) ist wichtiger als direkter Ausdruck.', fact: 'Wenn ein Japaner „ちょっと..." (chotto) sagt, bedeutet es meist indirekt „nein".' },
    'jp-c5': { title: 'Hanami - Blütenschau', body: 'Hanami (花見) ist die Tradition, sich im Frühling unter Kirschbäumen zu versammeln. Verbunden mit Mono no Aware (物の哀れ).', fact: 'Die Kirschblütenzeit dauert nur 1-2 Wochen. Japan hat eine offizielle „Blütenvorhersage".' },
    'fr-c1': { title: 'Das Baguette: Weltkulturerbe', body: 'Das Baguette wurde 2022 zum UNESCO-Weltkulturerbe erklärt. Ein Franzose isst durchschnittlich ein halbes Baguette pro Tag.', fact: 'Paris veranstaltet jährlich einen Baguette-Wettbewerb. Der Gewinner liefert ein Jahr lang Brot an den Élysée-Palast.' },
    'fr-c2': { title: 'La Bise - Der französische Gruß', body: 'La Bise (Wangenkuss) ist der übliche Gruß unter Bekannten. Die Anzahl variiert: 2 in Paris, 3 in der Provence, 4 in manchen Dörfern.', fact: 'Während COVID erfanden manche Franzosen den „Ellbogenkuss".' },
    'fr-c3': { title: 'Das Land der 400 Käse', body: 'De Gaulle sagte: „Wie regiert man ein Land mit 246 Käsesorten?" Heute hat Frankreich über 400 Sorten.', fact: 'Roquefort, der älteste Käse Frankreichs, reift in einer natürlichen Höhle.' },
    'fr-c4': { title: 'Der Eiffelturm - Ein temporärer „Fehler"', body: '1889 für die Weltausstellung gebaut, sollte er nach 20 Jahren abgerissen werden. Heute das meistbesuchte Bezahlmonument der Welt.', fact: 'Der Eiffelturm wächst im Sommer um ca. 15 cm durch Wärmeausdehnung.' },
    'fr-c5': { title: 'Französisches Kino', body: 'Frankreich ist die Geburtsstätte des Kinos. Die Brüder Lumière zeigten 1895 die erste öffentliche Vorführung in Paris.', fact: 'Frankreich hat mehr Kinos pro Kopf als jedes andere Land.' },
    'zh-c1': { title: 'Chinesisches Neujahr', body: 'Das Frühlingsfest (春节) ist Chinas wichtigste Feier. Es dauert 15 Tage. Familien verschenken rote Umschläge (红包) mit Geld.', fact: 'Zum chinesischen Neujahr finden über 3 Milliarden Reisen in 40 Tagen statt.' },
    'zh-c2': { title: 'Die Teezeremonie', body: 'Tee (茶) ist Chinas Nationalgetränk mit über 5.000 Jahren Kultur. Die Teezeremonie (茶道) verbindet Ästhetik und Philosophie.', fact: 'In China ist Tee einschenken eine Geste des Respekts. Mit den Fingern auf den Tisch klopfen heißt danke.' },
    'zh-c3': { title: 'Chinesische Schriftzeichen', body: 'Mandarin verwendet Schriftzeichen (汉字) mit über 3.000 Jahren Geschichte. Zwei Systeme: vereinfacht und traditionell.', fact: 'Das komplexeste Zeichen hat 64 Striche. Das Kangxi-Wörterbuch enthält 47.035 Zeichen.' },
    'zh-c4': { title: 'Die acht Küchen Chinas', body: 'China hat acht regionale Kochtraditionen: Sichuan (scharf), Kantonesisch (Dim Sum), Shandong (Meeresfrüchte) usw.', fact: 'Teigtaschen (饺子) werden zu Neujahr gegessen, da sie an antike Goldbarren erinnern.' },
    'zh-c5': { title: 'Das Konzept von 面子 (Miànzi)', body: 'Miànzi (面子) oder „Gesicht" ist fundamental in der chinesischen Kultur. Das Gesicht zu verlieren bedeutet sozialen Respektverlust.', fact: 'Beim Abendessen um die Rechnung zu kämpfen ist eine Form, Gesicht zu geben.' },
    'de-c1': { title: 'Oktoberfest und Bierkultur', body: 'Deutschland hat über 1.300 Brauereien und das Reinheitsgebot von 1516. Das Münchner Oktoberfest zieht über 6 Millionen Besucher an.', fact: 'Das Oktoberfest beginnt tatsächlich im September. Ursprünglich war es die Hochzeitsfeier von König Ludwig I.' },
    'de-c2': { title: 'Weihnachtsmärkte', body: 'Deutsche Weihnachtsmärkte sind weltberühmt. Der älteste in Dresden (Striezelmarkt) stammt von 1434.', fact: 'Der Weihnachtsbaum ist eine deutsche Tradition, die durch Prinz Albert weltweit verbreitet wurde.' },
    'de-c3': { title: 'Autobahn und deutsche Ingenieurskunst', body: 'Die Autobahn ist berühmt für fehlende Tempolimits. Deutschland ist Heimat von Mercedes, BMW, Porsche, Audi und VW.', fact: 'Nur 30% der Autobahn haben kein Tempolimit. Richtgeschwindigkeit: 130 km/h.' },
    'de-c4': { title: 'Das Land der klassischen Musik', body: 'Deutschland gab der Welt Bach, Beethoven, Brahms, Wagner und Händel. Die Berliner Philharmoniker gehören zu den besten Orchestern.', fact: 'Beethoven komponierte seine Neunte Symphonie völlig taub. Die „Ode an die Freude" ist die EU-Hymne.' },
    'de-c5': { title: 'Pünktlichkeit und Recycling', body: 'Deutsche schätzen Pünktlichkeit sehr. 5 Minuten Verspätung gilt als unhöflich. Weltführer im Recycling mit dem Pfandsystem.', fact: 'Deutschland recycelt 67% seiner Abfälle — die höchste Rate weltweit.' },
    'it-c1': { title: 'Pasta: über 300 Formen', body: 'Italien hat über 300 Pastasorten, jede für eine bestimmte Sauce. Immer „al dente" gekocht.', fact: 'Italiener essen 23 kg Pasta pro Person/Jahr. Ketchup auf Pasta ist fast ein Verbrechen.' },
    'it-c2': { title: 'Espresso-Kultur', body: 'Kaffee in Italien ist ein soziales Ritual. Espresso wird stehend an der Bar getrunken. Cappuccino nur morgens.', fact: 'Italien hat über 200.000 Kaffeebars. Der Espresso-Preis am Tresen ist in vielen Städten staatlich reguliert.' },
    'it-c3': { title: 'Commedia dell\'Arte', body: 'Im 16. Jh. in Italien entstanden, ist sie die Basis des modernen Theaters. Arlecchino, Pulcinella und Colombina waren Archetypen mit Masken.', fact: 'Pulcinella ist der Vorfahre des englischen Punch und des französischen Polichinelle.' },
    'it-c4': { title: 'Italienische Gesten', body: 'Italien ist berühmt für Gestenkommunikation mit über 250 anerkannten Gesten.', fact: '2020 wurde die „gekniffene Hand"-Geste zum offiziellen Emoji (🤌).' },
    'it-c5': { title: 'Calcio und Sportleidenschaft', body: 'Fußball (Calcio) ist mehr als Sport in Italien. 4 WM-Titel. Sonntagsfußball ist heilig.', fact: 'Der „Calcio Storico" in Florenz ist ein Sport aus dem 16. Jh., der Fußball, Rugby und Ringen kombiniert.' },
    'pt-c1': { title: 'Saudade und Fado', body: 'Saudade ist ein unübersetzbares Wort: eine Mischung aus Nostalgie und Sehnsucht. Fado drückt die Saudade aus, UNESCO-Erbe seit 2011.', fact: 'Amália Rodrigues war so wichtig, dass Portugal drei Tage Staatstrauer ausrief.' },
    'pt-c2': { title: 'Brasilianischer Fußball: Jogo Bonito', body: 'Brasilien hat 5 WM-Titel gewonnen. „Jogo Bonito" betont Kreativität und Freude.', fact: 'Das Maracanã hatte 1950 einmal 200.000 Zuschauer.' },
    'pt-c3': { title: 'Karneval in Rio', body: 'Der Karneval in Rio ist das größte Volksfest der Welt mit über 2 Millionen Menschen täglich auf den Straßen.', fact: 'Jede Sambaschule gibt 2-5 Millionen Dollar für ihren Umzug aus.' },
    'pt-c4': { title: 'Pastéis de Nata', body: 'Pastéis de Nata sind Portugals berühmteste Süßigkeit, im 18. Jh. von Mönchen kreiert.', fact: 'Pastéis de Belém verkauft über 20.000 Stück pro Tag. Nur 3 Personen kennen das Originalrezept.' },
    'pt-c5': { title: 'Portugiesische Entdeckungen', body: 'Im 15.-16. Jh. war Portugal die erste globale Seemacht. Vasco da Gama erreichte Indien, Cabral entdeckte Brasilien.', fact: 'Portugal hat die älteste noch betriebene Buchhandlung der Welt: Livraria Bertrand, seit 1732.' },
    'ko-c1': { title: 'K-Pop und Hallyu', body: 'Die „Koreanische Welle" (한류) hat Südkorea zur Kultursupermacht gemacht. K-Pop generiert Milliarden.', fact: 'BTS generierte ca. 5 Milliarden Dollar jährlich für die südkoreanische Wirtschaft.' },
    'ko-c2': { title: 'Kimchi: Seele des koreanischen Tisches', body: 'Kimchi ist fermentiertes Gemüse mit Chili, Knoblauch und Ingwer. Jede Familie hat ihr eigenes Rezept.', fact: 'Südkorea hat über 200 Kimchi-Sorten.' },
    'ko-c3': { title: 'Hangul: Das wissenschaftliche Alphabet', body: 'König Sejong schuf Hangul (한글) 1443. Es gilt als eines der wissenschaftlichsten Schriftsysteme mit 14 Konsonanten und 10 Vokalen.', fact: 'Hangul kann in wenigen Stunden gelernt werden. Der 9. Oktober ist Hangul-Tag.' },
    'ko-c4': { title: 'Jjimjilbang: Badekultur', body: 'Jjimjilbang (찜질방) sind 24/7 geöffnete koreanische Saunen — soziale Räume zum Entspannen und Schlafen.', fact: 'Viele Koreaner übernachten im Jjimjilbang, wenn sie den letzten Zug verpassen. Nur 8-12 Dollar.' },
    'ko-c5': { title: 'Koreanisches Bildungsfieber', body: 'Südkorea hat eine der intensivsten Bildungskulturen. Die Suneung-Prüfung (수능) bestimmt die Uni-Zukunft.', fact: 'Am Suneung-Tag eskortiert die Polizei verspätete Schüler, und die Nation schweigt während der Hörtests.' },
    'ru-c1': { title: 'Die Matroschka', body: 'Russische Schachtelpuppen (матрёшка) sind Russlands bekanntestes Symbol. Sie stehen für Mutterschaft und Fruchtbarkeit.', fact: 'Die größte Matroschka hat 51 Teile und ist 1 Meter hoch.' },
    'ru-c2': { title: 'Samowar und Teekultur', body: 'Der Samowar erwärmt Wasser für Tee. Die russische Teezeit umfasst Varenye (hausgemachte Marmelade) und lange Gespräche.', fact: 'Russen trinken 1,3 kg Tee pro Person/Jahr.' },
    'ru-c3': { title: 'Die russische Seele und Literatur', body: 'Die „russische Seele" (русская душа) beschreibt die emotionale Tiefe, reflektiert in Dostojewski, Tolstoi und Tschechow.', fact: 'Tolstoi schrieb „Krieg und Frieden" mit über 580 Figuren.' },
    'ru-c4': { title: 'Der russische Winter', body: 'Der Winter prägt die russische Kultur. Temperaturen bis -50°C in Sibirien. Masleniza wird mit Blini und Lagerfeuern gefeiert.', fact: 'In Oimjakon erreichen Temperaturen -71,2°C. Kinder gehen bis -52°C zur Schule.' },
    'ru-c5': { title: 'Das sowjetische Weltraumzeitalter', body: 'Russland (UdSSR) war Pionier im All: erster Satellit (Sputnik), erster Mensch (Gagarin), erster Weltraumspaziergang (Leonow).', fact: 'Gagarin sagte „Поехали!" (Los geht\'s!) beim Start. Jeder Kosmonaut wiederholt es seitdem.' },
    'ar-c1': { title: 'Arabischer Kaffee und Gastfreundschaft', body: 'Arabischer Kaffee (قهوة عربية) ist ein Symbol der Gastfreundschaft. In kleinen Tassen serviert, mit Kardamom gewürzt.', fact: 'Um keinen Nachschub zu wollen, die Tasse hin und her schwenken.' },
    'ar-c2': { title: 'Arabische Kalligraphie als Kunst', body: 'Arabische Kalligraphie gilt als höchste Form der bildenden Kunst in der islamischen Welt.', fact: 'Arabische Kalligraphie ist seit 2021 UNESCO-Welterbe.' },
    'ar-c3': { title: 'Ramadan: Der heilige Monat', body: 'Ramadan ist der neunte Monat des islamischen Kalenders. Muslime fasten von Morgendämmerung bis Sonnenuntergang.', fact: 'Während Ramadan steigt der Dattelkonsum um 300%.' },
    'ar-c4': { title: 'Die Beduinen und die Wüste', body: 'Beduinen (بدو) sind Nomadenvölker der Wüste mit jahrtausendealten Traditionen absoluter Gastfreundschaft.', fact: 'Beduinen navigieren in der Wüste mit Sternen — so präzise wie GPS.' },
    'ar-c5': { title: 'Arabische Musik und die Oud', body: 'Die Oud (عود) ist das älteste Saiteninstrument des Nahen Ostens, Vorfahre der europäischen Laute.', fact: 'Um Kulthums Konzerte konnten 6 Stunden dauern.' },
    'hi-c1': { title: 'Diwali: Lichterfest', body: 'Diwali (दिवाली) feiert den Sieg des Lichts über die Dunkelheit. Familien zünden Diyas an, machen Rangoli und Feuerwerk.', fact: 'Diwali dauert 5 Tage. Satelliten fotografieren Indien heller leuchtend aus dem All.' },
    'hi-c2': { title: 'Indiens kulinarische Vielfalt', body: 'Indien hat 29 Bundesstaaten mit einzigartiger Küche. Der Norden bevorzugt Brot mit Curry, der Süden Reis mit Sambar.', fact: 'Indien produziert 70% der Weltgewürze. Chai wird 1 Milliarde Mal pro Tag getrunken.' },
    'hi-c3': { title: 'Die heilige Kuh', body: 'Die Kuh ist im Hinduismus heilig. Rindfleisch wird in weiten Teilen Indiens nicht gegessen. Kühe laufen frei umher.', fact: 'Indien hat über 300 Millionen Kühe. Manche Bundesstaaten haben „Kuh-Krankenhäuser".' },
    'hi-c4': { title: 'Holi: Fest der Farben', body: 'Holi (होली) feiert den Frühling. Menschen werfen Farbpulver (Gulal). Soziale Unterschiede verschwinden temporär.', fact: 'Holi-Pulver wurde ursprünglich aus Heilpflanzen wie Neem und Kurkuma hergestellt.' },
    'hi-c5': { title: 'Bollywood: Die Traumfabrik', body: 'Bollywood produziert über 1.500 Filme pro Jahr — mehr als Hollywood. Kino ist Indiens beliebteste Unterhaltung.', fact: 'Indien verkauft 3 Milliarden Kinokarten pro Jahr, 4x mehr als die USA.' },
    'tr-c1': { title: 'Türkischer Kaffee: Welterbe', body: 'Türkischer Kaffee (Türk kahvesi) ist seit 2013 UNESCO-Erbe. Im Cezve mit fein gemahlenem Kaffee zubereitet.', fact: 'Türkisches Sprichwort: „Eine Tasse Kaffee schafft eine 40-jährige Freundschaft."' },
    'tr-c2': { title: 'Das türkische Hamam', body: 'Das Hamam verbindet Hygiene und Geselligkeit. Das Ritual umfasst Dampf, Peeling mit Kese und Schaummassage.', fact: 'Das Çemberlitaş Hamamı wurde 1584 von Architekt Sinan entworfen und ist noch in Betrieb.' },
    'tr-c3': { title: 'Heißluftballons in Kappadokien', body: 'Kappadokien ist berühmt für Ballonfahrten über „Feenkamine" aus vulkanischem Gestein.', fact: 'Jeden Morgen starten bis zu 150 Ballons gleichzeitig über Kappadokien.' },
    'tr-c4': { title: 'Nazar Boncuğu (Böses Auge)', body: 'Das Nazar Boncuğu (blaues Auge) schützt vor dem „bösen Blick". Überall in der Türkei zu finden.', fact: 'Die Türkei produziert über 3 Millionen Amulette pro Jahr, hauptsächlich in Nazarköy.' },
    'tr-c5': { title: 'Türkische Küche: Brücke zwischen Welten', body: 'Die türkische Küche ist eine der drei großen Kochtraditionen. Das türkische Frühstück (Kahvaltı) ist ein Festmahl.', fact: '„Kahvaltı" bedeutet wörtlich „vor dem Kaffee". Türkisches Baklava kann 40 Schichten Filoteig haben.' },
    'en-c1': { title: 'Britische Teezeit', body: 'Der Afternoon Tea wurde 1840 von der Herzogin von Bedford erfunden. Mit Gurkensandwiches, Scones und Gebäck.', fact: 'Die Briten trinken 165 Millionen Tassen Tee pro Tag.' },
    'en-c2': { title: 'Angelsächsische Sportarten', body: 'England erfand Fußball, Cricket, Rugby und Tennis. Die USA schufen Baseball, Basketball und American Football.', fact: 'Fußballregeln wurden 1863 in einem Londoner Pub geschrieben.' },
    'en-c3': { title: 'Shakespeare und Theater', body: 'Shakespeare schrieb 37 Stücke und prägte über 1.700 Wörter, die noch heute verwendet werden.', fact: 'Niemand weiß genau, wie Shakespeare aussah. Die berühmten Porträts entstanden nach seinem Tod.' },
    'en-c4': { title: 'Fast Food und amerikanische Kultur', body: 'Die USA popularisierten Fast Food mit McDonald\'s (1955). Thanksgiving dreht sich um den Truthahn.', fact: 'Amerikaner essen 50 Milliarden Hamburger pro Jahr.' },
    'en-c5': { title: 'Der amerikanische Traum', body: 'Der Glaube, dass jeder durch harte Arbeit Erfolg haben kann, unabhängig von seiner Herkunft.', fact: 'Die Freiheitsstatue war ein Geschenk Frankreichs von 1886. Ihre 7 Zacken stehen für 7 Kontinente und 7 Meere.' },
    'es-c1': { title: 'Flamenco: Leidenschaft und Duende', body: 'Flamenco verbindet Cante, Toque und Baile. „Duende" verwandelt Darbietung in Transzendenz. UNESCO-Erbe seit 2010.', fact: 'Flamenco-Fußarbeit erreicht 12 Schläge pro Sekunde.' },
    'es-c2': { title: 'Feste und Traditionen', body: 'Spanien hat über 25.000 Volksfeste pro Jahr. San Fermín, Las Fallas und La Tomatina sind die bekanntesten.', fact: 'La Tomatina verbraucht über 150.000 Tomaten in einer Stunde.' },
    'es-c3': { title: 'Tapas: Soziales Essen', body: 'Tapas sind kleine Gerichte zum Teilen. Ursprünglich Brotscheiben, die auf das Glas gelegt wurden.', fact: 'In Granada und Salamanca sind Tapas noch kostenlos zum Getränk.' },
    'es-c4': { title: 'Die spanische Siesta', body: 'Die Siesta ist eine jahrhundertealte Tradition. Geschäfte schlossen von 14-17 Uhr. Verschwindet in Städten.', fact: 'Nur 18% der Spanier machen noch Siesta. Spanien hat eine Siesta-Meisterschaft.' },
    'es-c5': { title: 'Spanisch in der Welt', body: 'Spanisch ist Muttersprache von 500 Millionen Menschen in 21 Ländern. Zweitmeist gesprochene Muttersprache nach Mandarin.', fact: 'Die USA haben mehr Spanischsprechende als Spanien.' },
    'vi-c1': { title: 'Phở: Die Seele Vietnams', body: 'Phở ist eine Reisnudelsuppe mit aromatischer Brühe. Wird zu jeder Zeit gegessen, besonders zum Frühstück.', fact: 'Vietnam konsumiert 2 Millionen Schüsseln Phở pro Tag.' },
    'vi-c2': { title: 'Motorradkultur', body: 'Vietnam hat über 45 Millionen Motorräder für 100 Millionen Einwohner. Das Motorrad dient für alles.', fact: 'Lokale Regel in Hanoi: „Geh langsam und selbstbewusst, die Motorräder weichen dir aus."' },
    'vi-c3': { title: 'Tết: Vietnamesisches Neujahr', body: 'Tết Nguyên Đán ist der wichtigste Feiertag Vietnams. Familien reinigen das Haus und bereiten Bánh Chưng zu.', fact: 'Die erste Person, die an Tết die Schwelle übertritt (Xông Đất), bestimmt das Jahresglück.' },
    'vi-c4': { title: 'Reisterrassen', body: 'Die Reisterrassen von Sapa sind Meisterwerke der Agrartechnik der Hmong und Dao.', fact: '„Hast du Reis gegessen?" (Ăn cơm chưa?) ist ein täglicher Gruß wie „Wie geht\'s?"' },
    'vi-c5': { title: 'Nón Lá und Áo Dài', body: 'Der Nón Lá (Kegelhut) und der Áo Dài (langes Kleid) sind ikonische vietnamesische Symbole.', fact: 'Der längste Áo Dài maß 638 Meter, gefertigt von 20 Schneiderinnen in 3 Monaten.' },
    'th-c1': { title: 'Der Wai: Thailändischer Gruß', body: 'Der Wai (ไหว้) ist das Zusammenpressen der Handflächen mit Verneigung. Je höher die Hände, desto mehr Respekt.', fact: 'Thailänder machen den Wai auch vor Buddha-Statuen und Königsfotos.' },
    'th-c2': { title: 'Monarchie und König', body: 'Die thailändische Monarchie wird tief respektiert. Majestätsbeleidigung ist ein schweres Vergehen. Gelb ist die Königsfarbe.', fact: 'Thailänder stehen für die Königshymne vor jedem Film im Kino auf.' },
    'th-c3': { title: 'Street Food: Straßenküche', body: 'Thailand ist ein Street-Food-Paradies. Bangkok ist die beste Stadt der Welt für Straßenessen.', fact: 'Bangkok hat über 300.000 Straßenimbisse.' },
    'th-c4': { title: 'Der Elefant: Nationalsymbol', body: 'Der Elefant ist Thailands Nationaltier. Weiße Elefanten sind heilig und gehören dem König.', fact: 'Der Ausdruck „weißer Elefant" stammt von Thai-Königen, die sie an Höflinge verschenkten, die sie ruinieren wollten.' },
    'th-c5': { title: 'Theravada-Buddhismus', body: '95% der Thailänder sind Theravada-Buddhisten. Männer sollen mindestens einmal als Mönch ordiniert werden.', fact: 'Thailand hat über 40.000 buddhistische Tempel.' },
    'nl-c1': { title: 'Tulpen und Tulpenmanie', body: 'Tulpen kamen im 16. Jh. aus der Türkei. 1637 war die „Tulpenmanie" die erste Spekulationsblase der Geschichte.', fact: 'Der Keukenhof pflanzt jährlich 7 Millionen Zwiebeln.' },
    'nl-c2': { title: 'Das Fahrrad: Königin der Niederlande', body: 'Die Niederlande haben mehr Fahrräder als Einwohner: 23 Millionen Räder für 17 Millionen Menschen.', fact: '800.000 Fahrräder werden jährlich gestohlen. Aus Amsterdams Grachten werden 15.000 Räder gefischt.' },
    'nl-c3': { title: 'Gouda, Edamer und Käsetradition', body: 'Die Niederlande produzieren über 650 Millionen kg Käse pro Jahr.', fact: '60% des niederländischen Käses wird exportiert. Ein Niederländer isst 21 kg Käse pro Jahr.' },
    'nl-c4': { title: 'Der Kampf gegen das Wasser', body: 'Ein Drittel der Niederlande liegt unter dem Meeresspiegel. Polder und Deiche sind Ingenieurleistungen.', fact: '„Gott schuf die Welt, aber die Niederländer schufen Holland."' },
    'nl-c5': { title: 'Meister der Malerei', body: 'Die Niederlande gaben der Welt Rembrandt, Vermeer und Van Gogh.', fact: 'Van Gogh verkaufte nur ein Bild zu Lebzeiten. „Sternennacht" malte er in einer psychiatrischen Klinik.' },
    'pl-c1': { title: 'Pierogi: Polnische Teigtaschen', body: 'Pierogi sind Polens bekanntestes Gericht. Füllungen: Kartoffel-Käse, Fleisch, Sauerkraut-Pilze oder Obst.', fact: 'Der größte Pierogi wog über 100 kg. Jede polnische Familie hütet ihr Rezept.' },
    'pl-c2': { title: 'Heiligabend (Wigilia)', body: 'Wigilia ist Polens wichtigste Feier. Ein Extra-Gedeck für unerwartete Gäste. 12 fleischlose Gerichte.', fact: 'Stroh unter der Tischdecke erinnert an die Krippe.' },
    'pl-c3': { title: 'Chopin: Die Seele Polens', body: 'Chopins Klaviermusik gehört zur schönsten, die je geschrieben wurde. Der Chopin-Wettbewerb ist der prestigeträchtigste.', fact: 'Nach seinem Tod wurde Chopins Herz in einem Cognac-Glas nach Warschau geschmuggelt.' },
    'pl-c4': { title: 'Solidarność und Widerstandskraft', body: 'Polen wurde oft besetzt, bewahrte aber seine Identität. Solidarność half, den Kalten Krieg zu beenden.', fact: 'Polen verschwand 123 Jahre von der Landkarte (1795-1918), bewahrte aber seine Sprache.' },
    'pl-c5': { title: 'Die polnische Sprache', body: 'Polnisch gilt als eine der schwierigsten europäischen Sprachen mit 7 Fällen und Lauten wie „szcz".', fact: 'Das längste gebräuchliche polnische Wort hat 32 Buchstaben. Polen hat 5 Literatur-Nobelpreise.' },
  },

  it: {
    'jp-c1': { title: 'L\'arte dell\'おじぎ (Ojigi)', body: 'In Giappone, l\'inchino (おじぎ) è una forma fondamentale di comunicazione. Tre tipi: eshaku (15°), keirei (30°) e saikeirei (45°).', fact: 'Nella metropolitana di Tokyo, i conducenti si inchinano al treno vuoto per rispetto.' },
    'jp-c2': { title: 'L\'etichetta del sushi', body: 'Mangiare sushi ha regole: con le mani o bacchette (mai forchetta), si immerge il pesce (non il riso) nella soia, non si mescola il wasabi.', fact: 'Il sushi originale (narezushi) veniva fermentato per mesi. Il sushi moderno fu inventato a Tokyo come fast food.' },
    'jp-c3': { title: 'Shintoismo e templi', body: 'Il Giappone ha due religioni che coesistono: lo shintoismo (神道) e il buddismo. I santuari shinto hanno torii rossi, i templi buddisti incensieri.', fact: 'Il Giappone ha più di 80.000 santuari shinto — più dei minimarket.' },
    'jp-c4': { title: 'Tatemae e Honne', body: 'Tatemae (建前) è la "faccia pubblica", honne (本音) i veri sentimenti. L\'armonia del gruppo (和 wa) è più importante dell\'espressione diretta.', fact: 'Quando un giapponese dice "ちょっと..." (chotto), generalmente significa "no" indirettamente.' },
    'jp-c5': { title: 'Hanami - Contemplazione dei fiori', body: 'L\'hanami (花見) è la tradizione di riunirsi sotto i ciliegi in fiore in primavera. Legato al mono no aware (物の哀れ).', fact: 'La stagione dei sakura dura solo 1-2 settimane. Il Giappone ha una "previsione di fioritura" ufficiale.' },
    'fr-c1': { title: 'La baguette: patrimonio mondiale', body: 'La baguette è stata dichiarata Patrimonio UNESCO nel 2022. Un francese consuma in media mezza baguette al giorno.', fact: 'Parigi organizza un concorso annuale della migliore baguette. Il vincitore fornisce pane all\'Eliseo per un anno.' },
    'fr-c2': { title: 'La bise - Il saluto francese', body: 'La bise è il saluto standard tra conoscenti in Francia. Il numero varia per regione: 2 a Parigi, 3 in Provenza.', fact: 'Durante il COVID, alcuni francesi inventarono il "bacio del gomito".' },
    'fr-c3': { title: 'Il paese dei 400 formaggi', body: 'De Gaulle disse: "Come governare un paese con 246 formaggi?" Oggi la Francia ne ha oltre 400.', fact: 'Il Roquefort, il formaggio più antico di Francia, matura nella sua grotta naturale.' },
    'fr-c4': { title: 'La Torre Eiffel - Un "errore" temporaneo', body: 'Costruita nel 1889, doveva essere demolita dopo 20 anni. Oggi è il monumento a pagamento più visitato al mondo.', fact: 'La Torre Eiffel cresce di circa 15 cm d\'estate per la dilatazione termica del ferro.' },
    'fr-c5': { title: 'Il cinema francese', body: 'La Francia è la culla del cinema. I fratelli Lumière fecero la prima proiezione pubblica nel 1895 a Parigi.', fact: 'La Francia ha più cinema pro capite di qualsiasi altro paese.' },
    'zh-c1': { title: 'Capodanno cinese', body: 'La Festa di Primavera (春节) è la celebrazione più importante della Cina. Dura 15 giorni. Le famiglie danno buste rosse (红包) con denaro.', fact: 'Durante il Capodanno cinese avvengono più di 3 miliardi di viaggi in 40 giorni.' },
    'zh-c2': { title: 'La cerimonia del tè', body: 'Il tè (茶) è la bevanda nazionale della Cina con oltre 5.000 anni di cultura. La cerimonia del tè (茶道) unisce estetica e filosofia.', fact: 'In Cina, servire il tè è un gesto di rispetto. Battere le dita sul tavolo significa grazie senza interrompere.' },
    'de-c1': { title: 'Oktoberfest e cultura birraria', body: 'La Germania ha oltre 1.300 birrifici e la legge della purezza (Reinheitsgebot) del 1516. L\'Oktoberfest attira oltre 6 milioni di visitatori.', fact: 'L\'Oktoberfest inizia in realtà a settembre. Originariamente era una festa di nozze.' },
    'it-c1': { title: 'La pasta: oltre 300 forme', body: 'L\'Italia ha oltre 300 tipi di pasta, ognuno per una salsa specifica. Sempre cotta "al dente".', fact: 'Gli italiani consumano 23 kg di pasta a persona all\'anno. Mettere il ketchup è quasi un crimine.' },
    'it-c2': { title: 'La cultura dell\'espresso', body: 'Il caffè in Italia è un rituale sociale. L\'espresso si beve in piedi al bancone. Il cappuccino solo al mattino.', fact: 'L\'Italia ha oltre 200.000 bar. Il prezzo dell\'espresso al bancone è regolato dal governo.' },
    'it-c3': { title: 'La Commedia dell\'Arte', body: 'Nata in Italia nel XVI secolo, è la base del teatro moderno. Arlecchino, Pulcinella e Colombina erano archetipi con maschere.', fact: 'Pulcinella è l\'antenato del Punch inglese. Il Carnevale di Venezia mantiene viva la tradizione delle maschere.' },
    'it-c4': { title: 'I gesti italiani', body: 'L\'Italia è famosa per la comunicazione gestuale con oltre 250 gesti riconosciuti.', fact: 'Nel 2020 il gesto della mano a carciofo è diventato emoji ufficiale (🤌).' },
    'it-c5': { title: 'Il calcio e la passione sportiva', body: 'Il calcio è più che uno sport in Italia. 4 Coppe del Mondo vinte. La domenica di calcio è sacra.', fact: 'Il "calcio storico" di Firenze è uno sport del XVI sec. che combina calcio, rugby e lotta.' },
    'es-c1': { title: 'Flamenco: passione e duende', body: 'Il flamenco combina cante, toque e baile. Il "duende" trasforma l\'esibizione in trascendenza. Patrimonio UNESCO dal 2010.', fact: 'Il zapateado flamenco può raggiungere 12 colpi al secondo.' },
    'en-c1': { title: 'L\'ora del tè britannico', body: 'L\'afternoon tea fu inventato nel 1840 dalla Duchessa di Bedford. Include tramezzini al cetriolo, scone e pasticcini.', fact: 'I britannici bevono 165 milioni di tazze di tè al giorno.' },
    'pt-c1': { title: 'Saudade e Fado', body: 'Saudade è una parola portoghese intraducibile: un misto di nostalgia e malinconia. Il Fado la esprime, patrimonio UNESCO dal 2011.', fact: 'Amália Rodrigues fu così importante che il Portogallo dichiarò tre giorni di lutto nazionale.' },
    'ko-c1': { title: 'K-Pop e Hallyu', body: 'La "Onda Coreana" (한류) ha trasformato la Corea del Sud in superpotenza culturale. Il K-Pop genera miliardi.', fact: 'BTS ha generato circa 5 miliardi di dollari l\'anno per l\'economia sudcoreana.' },
    'ru-c1': { title: 'La Matrioska', body: 'Le bambole russe (матрёшка) sono il simbolo più riconoscibile della Russia. Rappresentano maternità e fertilità.', fact: 'La matrioska più grande ha 51 pezzi ed è alta 1 metro.' },
    'ar-c1': { title: 'Caffè arabo e ospitalità', body: 'Il caffè arabo (قهوة عربية) è simbolo di ospitalità. Servito in tazzine senza manico, aromatizzato al cardamomo.', fact: 'Per rifiutare altro caffè, agitare la tazzina di lato. Se resta ferma, ne verseranno altro.' },
    'hi-c1': { title: 'Diwali: Festival delle Luci', body: 'Diwali (दिवाली) celebra il trionfo della luce sulle tenebre. Le famiglie accendono diya, fanno rangoli e sparano fuochi.', fact: 'Diwali dura 5 giorni. I satelliti fotografano l\'India più luminosa dallo spazio.' },
    'tr-c1': { title: 'Caffè turco: patrimonio mondiale', body: 'Il caffè turco (Türk kahvesi) è patrimonio UNESCO dal 2013. Preparato nel cezve con caffè finemente macinato.', fact: 'Proverbio turco: "Una tazza di caffè crea un\'amicizia di 40 anni."' },
    'vi-c1': { title: 'Phở: l\'anima del Vietnam', body: 'Il phở è una zuppa di noodle di riso con brodo aromatico. Si mangia a qualsiasi ora, specialmente a colazione.', fact: 'Il Vietnam consuma 2 milioni di ciotole di phở al giorno.' },
    'th-c1': { title: 'Il Wai: saluto tailandese', body: 'Il wai (ไหว้) consiste nel premere i palmi delle mani insieme e inclinare la testa. Più alte le mani, più rispetto.', fact: 'I tailandesi fanno il wai anche alle statue di Buddha e alle foto reali.' },
    'nl-c1': { title: 'Tulipani e Tulipomania', body: 'I tulipani arrivarono dalla Turchia nel XVI sec. Nel 1637 la "Tulipomania" fu la prima bolla speculativa della storia.', fact: 'Il parco Keukenhof pianta 7 milioni di bulbi ogni anno.' },
    'pl-c1': { title: 'Pierogi: ravioli polacchi', body: 'I pierogi sono il piatto più iconico della Polonia. Ripieni: patate e formaggio, carne, crauti e funghi.', fact: 'Il pierogi più grande pesava oltre 100 kg.' },
  },
};
